#!/usr/bin/env python3
import json
import re
import os
from collections import Counter
import math

# Try imports, will install packages in shell if missing when running
import sys
try:
    import pandas as pd
    import numpy as np
    from scipy.stats import chi2_contingency
    import matplotlib
    matplotlib.use('Agg')
    import matplotlib.pyplot as plt
except Exception as e:
    # If the environment doesn't have required packages, raise and let the shell pip install
    raise


def safe_lower(x):
    return '' if pd.isna(x) else str(x).lower()


def clean_text(text):
    if pd.isna(text):
        return ''
    s = str(text).lower()
    # remove non-alphanumeric and spaces
    s = re.sub(r'[^0-9a-z\s]+', ' ', s)
    # collapse whitespace
    s = re.sub(r'\s+', ' ', s).strip()
    return s


def contains_question(raw_text):
    if pd.isna(raw_text):
        return False
    t = str(raw_text)
    if '?' in t:
        return True
    # check for question words as whole words
    return bool(re.search(r'\b(what|how|why|when|where)\b', t, flags=re.IGNORECASE))


def count_urgency(text):
    if not text:
        return 0
    words = re.findall(r'\b(urgent|asap|emergency|critical|immediate)\b', text, flags=re.IGNORECASE)
    return len(words)


def rule_matches(rule, row):
    # rule is a dict. Support several possible keys: 'keywords', 'any_keywords', 'regex', 'priority', 'priority_in', 'hours', 'hour_range', 'urgency_min'
    txt = row['_combined_clean']
    raw = row['_combined_raw']
    # keywords (all)
    if 'keywords' in rule:
        kws = [str(k).lower() for k in rule['keywords']]
        for k in kws:
            if k not in txt:
                return False
    if 'any_keywords' in rule:
        kws = [str(k).lower() for k in rule['any_keywords']]
        if not any(k in txt for k in kws):
            return False
    if 'contains' in rule:
        if str(rule['contains']).lower() not in txt:
            return False
    if 'regex' in rule:
        try:
            if not re.search(rule['regex'], raw, flags=re.IGNORECASE):
                return False
        except Exception:
            # invalid regex: fail-safe
            return False
    if 'priority' in rule:
        # match exact
        pr = row.get('priority')
        if isinstance(rule['priority'], list):
            if pr not in rule['priority']:
                return False
        else:
            if pr != rule['priority']:
                return False
    if 'priority_in' in rule:
        pr = row.get('priority')
        if pr not in rule['priority_in']:
            return False
    if 'hours' in rule:
        if row.get('hour_of_day') not in rule['hours']:
            return False
    if 'hour_range' in rule:
        hr = row.get('hour_of_day')
        start, end = rule['hour_range']
        if not (start <= hr <= end):
            return False
    if 'urgency_min' in rule:
        if row.get('urgency_indicators', 0) < rule['urgency_min']:
            return False
    # If rule has condition 'manual_tag' match
    if 'manual_tag' in rule:
        if row.get('manual_tag') != rule['manual_tag']:
            return False
    # If 'must_have_question' flag
    if rule.get('must_have_question'):
        if not row.get('contains_question'):
            return False
    return True


def main():
    app_dir = '/app'
    csv_path = os.path.join(app_dir, 'tickets_raw.csv')
    rules_path = os.path.join(app_dir, 'tagging_rules.json')
    out_csv = os.path.join(app_dir, 'tickets_processed.csv')
    out_json = os.path.join(app_dir, 'analysis_report.json')
    vis_dir = os.path.join(app_dir, 'visualizations')
    os.makedirs(vis_dir, exist_ok=True)
    vis_path = os.path.join(vis_dir, 'hourly_discrepancy.png')

    required_cols = ['ticket_id', 'created_at', 'subject', 'description', 'manual_tag', 'priority']

    data_issues = []
    missing_columns = []

    # Load data
    try:
        df = pd.read_csv(csv_path)
    except Exception as e:
        raise RuntimeError(f'Failed to read CSV: {e}')

    total_tickets = int(len(df))

    # Validate required columns
    for c in required_cols:
        if c not in df.columns:
            missing_columns.append(c)
    if missing_columns:
        data_issues.append('Missing required columns: ' + ','.join(missing_columns))

    # Check for nulls in required columns
    for c in required_cols:
        if c in df.columns:
            null_count = int(df[c].isna().sum())
            if null_count > 0:
                data_issues.append(f'Column {c} has {null_count} missing values')

    # Parse created_at to datetime and extract hour
    if 'created_at' in df.columns:
        try:
            df['created_at_parsed'] = pd.to_datetime(df['created_at'], errors='coerce')
            invalid_ts = int(df['created_at_parsed'].isna().sum())
            if invalid_ts > 0:
                data_issues.append(f'{invalid_ts} invalid created_at timestamps')
            df['hour_of_day'] = df['created_at_parsed'].dt.hour.fillna(-1).astype(int)
            # ensure hours in 0-23, invalid become -1
        except Exception as e:
            data_issues.append('Failed to parse created_at: ' + str(e))
            df['hour_of_day'] = -1
    else:
        df['hour_of_day'] = -1

    # Create raw combined text and cleaned versions
    df['_combined_raw'] = (df.get('subject', '').fillna('') + ' ' + df.get('description', '').fillna(''))
    df['_combined_clean'] = df['_combined_raw'].apply(clean_text)
    df['cleaned_subject'] = df.get('subject', '').apply(clean_text)
    df['cleaned_description'] = df.get('description', '').apply(clean_text)

    # Features
    df['word_count'] = df['_combined_clean'].apply(lambda s: len(s.split()) if s else 0)
    df['contains_question'] = df['_combined_raw'].apply(contains_question)
    df['urgency_indicators'] = df['_combined_clean'].apply(count_urgency)
    # hour_of_day already present; if not, kept as -1

    # Load rules
    try:
        with open(rules_path, 'r') as f:
            rules_obj = json.load(f)
    except Exception as e:
        raise RuntimeError(f'Failed to read rules JSON: {e}')

    # rules may be either a list or a dict containing 'rules'
    if isinstance(rules_obj, dict) and 'rules' in rules_obj:
        rules = rules_obj['rules']
    elif isinstance(rules_obj, list):
        rules = rules_obj
    else:
        # Unknown format
        raise RuntimeError('Unknown tagging_rules.json format; expected list or {"rules": [...]}')

    # Apply rules in priority order (list order)
    auto_tags = []
    for idx, row in df.iterrows():
        assigned = None
        for rule in rules:
            if not isinstance(rule, dict):
                continue
            # rule should define a tag name
            tag = rule.get('tag') or rule.get('auto_tag') or rule.get('label')
            if tag is None:
                continue
            if rule_matches(rule, row):
                assigned = tag
                break
        if assigned is None:
            assigned = 'uncategorized'
        auto_tags.append(assigned)

    df['auto_tag'] = auto_tags

    # Compare to manual_tag
    # treat NaN manual_tag as different
    df['manual_tag_filled'] = df['manual_tag'].fillna('')
    df['tag_discrepancy'] = df.apply(lambda r: False if (str(r['manual_tag_filled']) == str(r['auto_tag'])) else True, axis=1)

    # Prepare processed CSV with required columns: original columns plus new ones
    # Keep original column order, then append specified new columns
    original_cols = [c for c in df.columns if c in list(df.columns) and c in []]  # placeholder
    # Use the required original columns if present in input, otherwise include whatever existed
    out_cols = []
    for c in ['ticket_id', 'created_at', 'subject', 'description', 'manual_tag', 'priority']:
        if c in df.columns:
            out_cols.append(c)
    # now append new required fields
    new_cols = ['cleaned_subject', 'cleaned_description', 'word_count', 'contains_question', 'urgency_indicators', 'hour_of_day', 'auto_tag', 'tag_discrepancy']
    out_cols.extend(new_cols)

    # Save processed CSV
    df_out = df[out_cols]
    df_out.to_csv(out_csv, index=False)

    # Statistical analysis
    # Overall accuracy
    df['match'] = ~df['tag_discrepancy']
    overall_accuracy = float(df['match'].mean()) if len(df) > 0 else 0.0

    # Accuracy by priority: expected priorities 'low','medium','high'
    accuracy_by_priority = {}
    for p in ['low', 'medium', 'high']:
        sub = df[df['priority'] == p]
        if len(sub) == 0:
            accuracy_by_priority[p] = 0.0
        else:
            accuracy_by_priority[p] = float(sub['match'].mean())

    # Most common discrepancy types (manual_tag -> auto_tag) with counts
    discrepancies = df[df['tag_discrepancy']]
    most_common = []
    if len(discrepancies) > 0:
        grp = discrepancies.groupby(['manual_tag', 'auto_tag']).size().reset_index(name='count')
        grp = grp.sort_values('count', ascending=False).head(10)
        for _, r in grp.iterrows():
            manual_t = '' if pd.isna(r['manual_tag']) else str(r['manual_tag'])
            auto_t = '' if pd.isna(r['auto_tag']) else str(r['auto_tag'])
            most_common.append({'manual_tag': manual_t, 'auto_tag': auto_t, 'count': int(r['count'])})

    # Chi-square test: contingency table hours (0-23) vs discrepancy (True/False)
    # Build 24x2 table for hours 0..23, include hour -1 as 'unknown' excluded for chi-square
    table = []
    hours = list(range(0, 24))
    for h in hours:
        sub = df[df['hour_of_day'] == h]
        true_cnt = int(sub['tag_discrepancy'].sum())
        false_cnt = int((~sub['tag_discrepancy']).sum())
        table.append([true_cnt, false_cnt])
    # If all zeros or invalid shape, fallback
    try:
        chi2_stat = 0.0
        p_value = 1.0
        discrepancy_independent = True
        # Need at least 2 non-zero rows for meaningful chi2; otherwise return defaults
        if sum(sum(r) for r in table) > 0 and any(sum(r) > 0 for r in table):
            chi2, p, dof, ex = chi2_contingency(table)
            chi2_stat = float(chi2)
            p_value = float(p)
            discrepancy_independent = bool(p_value > 0.05)
    except Exception as e:
        chi2_stat = 0.0
        p_value = 1.0
        discrepancy_independent = True

    # Identify 3 hours with highest discrepancy rates (only consider hours with at least 1 ticket)
    rates = []
    for h in hours:
        sub = df[df['hour_of_day'] == h]
        if len(sub) == 0:
            continue
        rate = float(sub['tag_discrepancy'].mean())
        rates.append((h, rate, len(sub)))
    rates_sorted = sorted(rates, key=lambda x: (-x[1], -x[2], x[0]))
    top3_hours = [int(h) for h, _, _ in rates_sorted[:3]]
    # If fewer than 3 hours with data, pad with -1 or leave as is. We'll pad with -1 if needed to ensure length 3
    while len(top3_hours) < 3:
        top3_hours.append(-1)

    # Feature statistics
    avg_word_count = float(df['word_count'].mean()) if len(df) > 0 else 0.0
    question_percentage = float(df['contains_question'].mean()) if len(df) > 0 else 0.0
    urgency_percentage = float((df['urgency_indicators'] > 0).mean()) if len(df) > 0 else 0.0

    report = {
        'data_validation': {
            'total_tickets': total_tickets,
            'missing_columns': missing_columns,
            'data_issues': data_issues
        },
        'tagging_accuracy': {
            'overall_accuracy': overall_accuracy,
            'accuracy_by_priority': {
                'low': accuracy_by_priority['low'],
                'medium': accuracy_by_priority['medium'],
                'high': accuracy_by_priority['high']
            },
            'most_common_discrepancies': most_common
        },
        'temporal_analysis': {
            'chi2_statistic': chi2_stat,
            'chi2_pvalue': p_value,
            'discrepancy_independent': discrepancy_independent,
            'high_discrepancy_hours': top3_hours
        },
        'feature_statistics': {
            'avg_word_count': avg_word_count,
            'question_percentage': question_percentage,
            'urgency_percentage': urgency_percentage
        }
    }

    # Save report
    with open(out_json, 'w') as f:
        json.dump(report, f, indent=2)

    # Optional: save hourly discrepancy plot
    try:
        hours_plot = list(range(0, 24))
        rates_plot = []
        for h in hours_plot:
            sub = df[df['hour_of_day'] == h]
            if len(sub) == 0:
                rates_plot.append(0.0)
            else:
                rates_plot.append(float(sub['tag_discrepancy'].mean()))
        plt.figure(figsize=(10,4))
        plt.bar(hours_plot, rates_plot, color='tab:orange')
        plt.xlabel('Hour of day')
        plt.ylabel('Discrepancy rate')
        plt.title('Discrepancy rate by hour of day')
        plt.xticks(hours_plot)
        plt.ylim(0,1)
        plt.tight_layout()
        plt.savefig(vis_path)
        plt.close()
    except Exception:
        pass

    print('Processing complete.')

if __name__ == '__main__':
    main()
