        bad_ts = int(df['created_at_parsed'].isna().sum())
        if bad_ts > 0:
            data_issues.append(f'{bad_ts} invalid created_at timestamps')
        df['hour_of_day'] = df['created_at_parsed'].dt.hour.fillna(-1).astype(int)
    else:
        df['hour_of_day'] = -1

    df['_combined_raw'] = (df.get('subject','').fillna('') + ' ' + df.get('description','').fillna(''))
    df['_combined_clean'] = df['_combined_raw'].apply(clean_text)

    # cleaned subject/description
    df['cleaned_subject'] = df.get('subject','').apply(clean_text)
    df['cleaned_description'] = df.get('description','').apply(clean_text)
    df['word_count'] = df['_combined_clean'].apply(lambda s: len(s.split()) if s else 0)

    # load rules
    try:
        with open(RULES_IN,'r') as f:
            rules_obj = json.load(f)
    except Exception as e:
        print('Failed to read rules JSON:', e, file=sys.stderr)
        sys.exit(1)

    if isinstance(rules_obj, dict):
        rules = rules_obj.get('tagging_rules') or rules_obj.get('rules') or []
    elif isinstance(rules_obj, list):
        rules = rules_obj
    else:
        print('Unknown rules JSON format', file=sys.stderr)
        sys.exit(1)

    question_words = rules_obj.get('question_words') if isinstance(rules_obj, dict) else None
    if not question_words:
        question_words = ['what','how','why','when','where','which','can','could','would']
    urgency_words = rules_obj.get('urgency_words') if isinstance(rules_obj, dict) else None
    if not urgency_words:
        urgency_words = ['urgent','asap','emergency','critical','immediate','important']

    df['contains_question'] = df['_combined_raw'].apply(lambda t: contains_question(t, question_words))
    df['urgency_indicators'] = df['_combined_clean'].apply(lambda t: count_urgency(t, urgency_words))

    # sort rules by priority ascending
    try:
        rules_sorted = sorted([r for r in rules if isinstance(r, dict)], key=lambda x: int(x.get('priority', 999)))
    except Exception:
        rules_sorted = [r for r in rules if isinstance(r, dict)]

    # apply rules
    auto_tags = []
    for idx, row in df.iterrows():
        assigned = None
        for rule in rules_sorted:
            tag = rule.get('tag') or rule.get('auto_tag') or rule.get('label')
            if tag is None:
                continue
            if rule_matches_any(rule, row):
                assigned = tag
                break
        if assigned is None:
            assigned = 'uncategorized'
        auto_tags.append(assigned)
    df['auto_tag'] = auto_tags

    df['manual_tag_filled'] = df['manual_tag'].fillna('')
    df['tag_discrepancy'] = df.apply(lambda r: False if (str(r['manual_tag_filled']) == str(r['auto_tag'])) else True, axis=1)

    # save processed CSV with exact required columns
    out_cols = [c for c in REQUIRED_COLS if c in df.columns]
    out_cols.extend(['cleaned_subject','cleaned_description','word_count','contains_question','urgency_indicators','hour_of_day','auto_tag','tag_discrepancy'])
    df[out_cols].to_csv(OUT_CSV, index=False)

    # stats
    df['match'] = ~df['tag_discrepancy']
    overall_accuracy = float(df['match'].mean()) if len(df)>0 else 0.0
    accuracy_by_priority = {}
    for p in ['low','medium','high']:
        sub = df[df['priority'] == p]
        accuracy_by_priority[p] = float(sub['match'].mean()) if len(sub)>0 else 0.0

    discrepancies = df[df['tag_discrepancy']]
    most_common = []
    if len(discrepancies)>0:
        grp = discrepancies.groupby(['manual_tag','auto_tag']).size().reset_index(name='count')
        grp = grp.sort_values('count', ascending=False).head(10)
        for _,r in grp.iterrows():
            manual_t = '' if pd.isna(r['manual_tag']) else str(r['manual_tag'])
            auto_t = '' if pd.isna(r['auto_tag']) else str(r['auto_tag'])
            most_common.append({'manual_tag': manual_t, 'auto_tag': auto_t, 'count': int(r['count'])})

    # chi-square
    table = []
    hours = list(range(0,24))
    for h in hours:
        sub = df[df['hour_of_day'] == h]
        true_cnt = int(sub['tag_discrepancy'].sum())
        false_cnt = int((~sub['tag_discrepancy']).sum())
        table.append([true_cnt, false_cnt])
    try:
        chi2_stat = 0.0
        p_value = 1.0
        discrepancy_independent = True
        total_counts = sum(sum(r) for r in table)
        nonzero_rows = sum(1 for r in table if sum(r)>0)
        if total_counts>0 and nonzero_rows>=2:
            chi2, p, dof, ex = chi2_contingency(table)
            chi2_stat = float(chi2)
            p_value = float(p)
            discrepancy_independent = bool(p_value > 0.05)
    except Exception:
        chi2_stat = 0.0
        p_value = 1.0
        discrepancy_independent = True

    rates = []
    for h in hours:
        sub = df[df['hour_of_day'] == h]
        if len(sub)==0: continue
        rates.append((h, float(sub['tag_discrepancy'].mean()), len(sub)))
    rates_sorted = sorted(rates, key=lambda x: (-x[1], -x[2], x[0]))
    top3 = [int(h) for h,_,_ in rates_sorted[:3]]
    while len(top3)<3: top3.append(-1)

    report = {
        'data_validation':{
            'total_tickets': int(total),
            'missing_columns': missing_columns,
            'data_issues': data_issues
        },
        'tagging_accuracy':{
            'overall_accuracy': overall_accuracy,
            'accuracy_by_priority':{
                'low': accuracy_by_priority['low'],
                'medium': accuracy_by_priority['medium'],
                'high': accuracy_by_priority['high']
            },
            'most_common_discrepancies': most_common
        },
        'temporal_analysis':{
            'chi2_statistic': chi2_stat,
            'chi2_pvalue': p_value,
            'discrepancy_independent': discrepancy_independent,
            'high_discrepancy_hours': top3
        },
        'feature_statistics':{
            'avg_word_count': float(df['word_count'].mean()) if len(df)>0 else 0.0,
            'question_percentage': float(df['contains_question'].mean()) if len(df)>0 else 0.0,
            'urgency_percentage': float((df['urgency_indicators']>0).mean()) if len(df)>0 else 0.0
        }
    }

    with open(OUT_JSON,'w') as f:
        json.dump(report, f, indent=2)

    # plot
    try:
        hours_plot = list(range(0,24))
        rates_plot = [0.0]*24
        for h in hours_plot:
            sub = df[df['hour_of_day']==h]
            rates_plot[h] = float(sub['tag_discrepancy'].mean()) if len(sub)>0 else 0.0
        plt.figure(figsize=(10,4))
        plt.bar(hours_plot, rates_plot, color='tab:blue')
        plt.xlabel('Hour of day')
        plt.ylabel('Discrepancy rate')
        plt.title('Discrepancy rate by hour of day')
        plt.xticks(hours_plot)
        plt.ylim(0,1)
        plt.tight_layout()
        plt.savefig(VIS_OUT)
        plt.close()
    except Exception:
        pass

    print('Wrote:', OUT_CSV)
    print('Wrote:', OUT_JSON)
    print('Wrote (optional):', VIS_OUT)

if __name__=='__main__':
    main()
