#!/usr/bin/env python3
import json
import re
import sys
from collections import Counter
from pathlib import Path

import numpy as np
import pandas as pd

# Optional imports
try:
    from scipy.stats import chi2_contingency
except Exception:
    chi2_contingency = None

try:
    import matplotlib.pyplot as plt
except Exception:
    plt = None

APP_DIR = Path('/app')
CSV_IN = APP_DIR / 'tickets_raw.csv'
RULES_IN = APP_DIR / 'tagging_rules.json'
CSV_OUT = APP_DIR / 'tickets_processed.csv'
REPORT_OUT = APP_DIR / 'analysis_report.json'
PLOT_OUT_DIR = APP_DIR / 'visualizations'
PLOT_OUT_DIR.mkdir(parents=True, exist_ok=True)
PLOT_OUT = PLOT_OUT_DIR / 'hourly_discrepancy.png'

REQUIRED_COLS = ['ticket_id', 'created_at', 'subject', 'description', 'manual_tag', 'priority']

# Utility cleaning
def clean_text(s):
    if pd.isna(s):
        return ''
    s = str(s).lower()
    # keep alphanumeric and spaces
    s = re.sub(r'[^a-z0-9\s]', ' ', s)
    s = re.sub(r'\s+', ' ', s).strip()
    return s

question_words = {'what', 'how', 'why', 'when', 'where'}
urgency_words = {'urgent', 'asap', 'emergency', 'critical', 'immediate'}

# Match a rule to text (supports keywords and regex), field can be 'subject','description','combined'
def match_rule(rule, subject, description, combined):
    field = rule.get('field', 'combined')
    if field == 'subject':
        text = subject
    elif field == 'description':
        text = description
    else:
        text = combined
    # Prefer exact keyword matching as whole words
    if 'keywords' in rule and isinstance(rule['keywords'], list):
        for kw in rule['keywords']:
            if re.search(r'\b' + re.escape(str(kw).lower()) + r'\b', text):
                return True
    if 'contains' in rule and isinstance(rule['contains'], list):
        for kw in rule['contains']:
            if re.search(r'\b' + re.escape(str(kw).lower()) + r'\b', text):
                return True
    if 'regex' in rule and isinstance(rule['regex'], str) and rule['regex'].strip():
        try:
            if re.search(rule['regex'], text):
                return True
        except re.error:
            # fallback to literal search
            if rule['regex'].lower() in text:
                return True
    # fallback: tag name in text
    if 'tag' in rule and isinstance(rule['tag'], str):
        if re.search(r'\b' + re.escape(rule['tag'].lower()) + r'\b', text):
            return True
    return False


def main():
    data_issues = []
    # Load CSV
    try:
        df = pd.read_csv(CSV_IN)
    except Exception as e:
        print(f'ERROR: could not read {CSV_IN}: {e}', file=sys.stderr)
        sys.exit(1)

    total_tickets = len(df)

    # Validate columns
    missing_columns = [c for c in REQUIRED_COLS if c not in df.columns]

    if missing_columns:
        data_issues.append(f'Missing required columns: {missing_columns}')

    # Normalize present required columns if any are missing, create empty columns to avoid crashes
    for c in REQUIRED_COLS:
        if c not in df.columns:
            df[c] = pd.NA

    # Check for high missingness
    for c in REQUIRED_COLS:
        pct_missing = df[c].isna().mean()
        if pct_missing > 0.2:
            data_issues.append(f'Column {c} has high missingness: {pct_missing:.2%}')

    # Parse created_at
    df['created_dt'] = pd.to_datetime(df['created_at'], errors='coerce')
    n_invalid_dates = df['created_dt'].isna().sum()
    if n_invalid_dates > 0:
        data_issues.append(f'created_at parsing failed for {n_invalid_dates} rows')

    # Text cleaning
    df['raw_subject'] = df['subject'].fillna('').astype(str)
    df['raw_description'] = df['description'].fillna('').astype(str)
    df['cleaned_subject'] = df['raw_subject'].str.lower().apply(lambda s: re.sub(r'[^a-z0-9\s]', ' ', s)).str.replace(r'\s+', ' ', regex=True).str.strip()
    df['cleaned_description'] = df['raw_description'].str.lower().apply(lambda s: re.sub(r'[^a-z0-9\s]', ' ', s)).str.replace(r'\s+', ' ', regex=True).str.strip()

    # Combined cleaned text
    df['combined_text'] = (df['cleaned_subject'] + ' ' + df['cleaned_description']).str.strip()
    # Combined raw for '?' detection
    df['combined_raw'] = (df['raw_subject'] + ' ' + df['raw_description']).str.lower()

    # Word count
    df['word_count'] = df['combined_text'].apply(lambda s: 0 if not s else len(s.split()))

    # contains_question: '?' in raw OR question words present in cleaned tokens
    def contains_question_fn(raw, cleaned):
        if '?' in raw:
            return True
        tokens = set(cleaned.split())
        return any(w in tokens for w in question_words)

    df['contains_question'] = df.apply(lambda r: contains_question_fn(r['combined_raw'], r['combined_text']), axis=1)

    # urgency_indicators count
    def urgency_count_fn(cleaned):
        if not cleaned:
            return 0
        cnt = 0
        tokens = cleaned.split()
        for u in urgency_words:
            cnt += tokens.count(u)
        return cnt

    df['urgency_indicators'] = df['combined_text'].apply(urgency_count_fn)

    # hour_of_day
    df['hour_of_day'] = df['created_dt'].dt.hour.fillna(-1).astype(int)
    # invalid hours set to -1; we'll handle them later

    # Load tagging rules
    try:
        with open(RULES_IN, 'r') as f:
            rules = json.load(f)
    except Exception as e:
        data_issues.append(f'Failed to load tagging rules: {e}')
        rules = []

    # If rules is a dict with 'rules' key, use that
    if isinstance(rules, dict) and 'rules' in rules and isinstance(rules['rules'], list):
        rules = rules['rules']

    # Apply rules in order (priority by list order)
    auto_tags = []
    for _, row in df.iterrows():
        subj = row['cleaned_subject']
        desc = row['cleaned_description']
        combined = row['combined_text']
        matched_tag = None
        for rule in rules:
            try:
                if match_rule(rule, subj, desc, combined):
                    matched_tag = rule.get('tag') or rule.get('name') or ''
                    break
            except Exception:
                continue
        if matched_tag is None or matched_tag == '':
            matched_tag = 'other'
        auto_tags.append(str(matched_tag))

    df['auto_tag'] = auto_tags

    # tag_discrepancy: compare manual_tag vs auto_tag
    df['manual_tag_filled'] = df['manual_tag'].fillna('').astype(str)
    df['tag_discrepancy'] = (df['manual_tag_filled'].str.strip().str.lower() != df['auto_tag'].str.strip().str.lower())

    # Prepare processed output columns: original columns + specified new ones
    out_cols = list(df.columns)  # we'll select final subset below
    required_new = ['cleaned_subject', 'cleaned_description', 'word_count', 'contains_question', 'urgency_indicators', 'hour_of_day', 'auto_tag', 'tag_discrepancy']

    # Ensure output includes original required cols in original order, then new ones
    final_cols = []
    for c in df.columns:
        if c in REQUIRED_COLS:
            final_cols.append(c)
    # Add other original columns that were present (besides created_dt/raws)
    extras = [c for c in df.columns if c not in final_cols and c not in required_new and c not in ['combined_text','combined_raw','created_dt','raw_subject','raw_description','manual_tag_filled']]
    final_cols += extras
    final_cols += required_new

    # Save processed CSV
    df.to_csv(CSV_OUT, columns=final_cols, index=False)

    # Statistics
    # Overall accuracy
    total = len(df)
    matches = (~df['tag_discrepancy']).sum()
    overall_accuracy = float(matches) / total if total > 0 else 0.0

    # Accuracy by priority (normalize values to low/medium/high keys)
    def norm_priority(p):
        if pd.isna(p):
            return 'unknown'
        s = str(p).lower().strip()
        if s in ('low', 'l'):
            return 'low'
        if s in ('medium', 'med', 'm'):
            return 'medium'
        if s in ('high', 'h'):
            return 'high'
        return s

    df['priority_norm'] = df['priority'].apply(norm_priority)
    acc_by_priority = {}
    for k in ['low', 'medium', 'high']:
        sub = df[df['priority_norm'] == k]
        if len(sub) == 0:
            acc_by_priority[k] = None
        else:
            acc_by_priority[k] = float((~sub['tag_discrepancy']).sum()) / len(sub)

    # Most common discrepancies
    discrep = df[df['tag_discrepancy']]
    pairs = list(zip(discrep['manual_tag_filled'].str.strip().str.lower(), discrep['auto_tag'].str.strip().str.lower()))
    counter = Counter(pairs)
    most_common = []
    for (m,a), cnt in counter.most_common(10):
        most_common.append({'manual_tag': m if m!='' else None, 'auto_tag': a if a!='' else None, 'count': int(cnt)})

    # Chi-square test: hours 0-23 vs discrepancy True/False
    # Build contingency table rows=24 hours, cols=[discrepant, not_discrepant]
    hours = list(range(24))
    table = []
    for h in hours:
        sub = df[df['hour_of_day'] == h]
        d = sub['tag_discrepancy'].sum()
        nd = len(sub) - d
        table.append([int(d), int(nd)])
    table = np.array(table)

    if chi2_contingency is not None and table.sum() > 0 and table.shape[0] > 1:
        try:
            chi2_stat, p, dof, exp = chi2_contingency(table)
        except Exception:
            chi2_stat, p = 0.0, 1.0
    else:
        chi2_stat, p = 0.0, 1.0

    discrepancy_independent = bool(p > 0.05)

    # Top 3 hours with highest discrepancy rates (only consider hours with at least one ticket)
    rates = []
    for h in hours:
        sub = df[df['hour_of_day'] == h]
        if len(sub) == 0:
            continue
        rate = sub['tag_discrepancy'].mean()
        rates.append((h, rate, len(sub)))
    rates_sorted = sorted(rates, key=lambda x: (-x[1], x[0]))
    top3_hours = [int(x[0]) for x in rates_sorted[:3]]

    # Feature statistics
    avg_word_count = float(df['word_count'].mean()) if total>0 else 0.0
    question_percentage = float(df['contains_question'].mean()) if total>0 else 0.0
    urgency_percentage = float((df['urgency_indicators'] > 0).mean()) if total>0 else 0.0

    # Build report dict
    report = {
        'data_validation': {
            'total_tickets': int(total_tickets),
            'missing_columns': missing_columns,
            'data_issues': data_issues
        },
        'tagging_accuracy': {
            'overall_accuracy': overall_accuracy,
            'accuracy_by_priority': {
                'low': acc_by_priority.get('low'),
                'medium': acc_by_priority.get('medium'),
                'high': acc_by_priority.get('high')
            },
            'most_common_discrepancies': [
                {'manual_tag': item['manual_tag'] if item['manual_tag'] is not None else '', 'auto_tag': item['auto_tag'] if item['auto_tag'] is not None else '', 'count': item['count']} for item in most_common
            ]
        },
        'temporal_analysis': {
            'chi2_statistic': float(chi2_stat),
            'chi2_pvalue': float(p),
            'discrepancy_independent': discrepancy_independent,
            'high_discrepancy_hours': top3_hours
        },
        'feature_statistics': {
            'avg_word_count': avg_word_count,
            'question_percentage': question_percentage,
            'urgency_percentage': urgency_percentage
        }
    }

    # Save report
    with open(REPORT_OUT, 'w') as f:
        json.dump(report, f, indent=2)

    # Optional plot
    if plt is not None and len(rates) > 0:
        hours_plot = [r[0] for r in sorted(rates, key=lambda x: x[0])]
        rates_plot = [r[1] for r in sorted(rates, key=lambda x: x[0])]
        plt.figure(figsize=(10,4))
        plt.bar(hours_plot, rates_plot)
        plt.xlabel('Hour of day')
        plt.ylabel('Discrepancy rate')
        plt.title('Discrepancy rate by hour of day')
        plt.xlim(-0.5,23.5)
        plt.ylim(0,1)
        plt.grid(axis='y', alpha=0.3)
        try:
            plt.savefig(PLOT_OUT, bbox_inches='tight')
        except Exception:
            pass

    print('Processing complete. Outputs:')
    print(f' - {CSV_OUT}')
    print(f' - {REPORT_OUT}')
    if PLOT_OUT.exists():
        print(f' - {PLOT_OUT}')

if __name__ == "__main__":
    main()
