    if pd.isna(s):
        return ''
    s = str(s).lower()
    s = re.sub(r'[^a-z0-9\s]', ' ', s)
    s = re.sub(r'\s+', ' ', s).strip()
    return s

# Match a rule to text
def match_rule(rule, text):
    # text is already cleaned lower-case
    if not isinstance(rule, dict):
        return False
    # keywords
    if 'keywords' in rule and isinstance(rule['keywords'], list):
        for kw in rule['keywords']:
            if not kw:
                continue
            # allow multi-word keywords
            pat = r'\b' + re.escape(str(kw).lower()) + r'\b'
            if re.search(pat, text):
                return True
    # contains alias
    if 'contains' in rule and isinstance(rule['contains'], list):
        for kw in rule['contains']:
            if re.search(r'\b' + re.escape(str(kw).lower()) + r'\b', text):
                return True
    # regex
    if 'regex' in rule and isinstance(rule['regex'], str) and rule['regex'].strip():
        try:
            if re.search(rule['regex'], text):
                return True
        except re.error:
            if rule['regex'].lower() in text:
                return True
    return False


def main():
    data_issues = []
    try:
        df = pd.read_csv(CSV_IN)
    except Exception as e:
        print(f'ERROR: could not read {CSV_IN}: {e}', file=sys.stderr)
        sys.exit(1)

    total_tickets = len(df)

    # Validate columns
    missing_columns = [c for c in REQUIRED_COLS if c not in df.columns]
    if missing_columns:
        data_issues.append(f'Missing required columns: {missing_columns}')
    for c in REQUIRED_COLS:
        if c not in df.columns:
            df[c] = pd.NA

    for c in REQUIRED_COLS:
        pct_missing = df[c].isna().mean()
        if pct_missing > 0.2:
            data_issues.append(f'Column {c} has high missingness: {pct_missing:.2%}')

    df['created_dt'] = pd.to_datetime(df['created_at'], errors='coerce')
    n_invalid_dates = df['created_dt'].isna().sum()
    if n_invalid_dates > 0:
        data_issues.append(f'created_at parsing failed for {n_invalid_dates} rows')

    # Clean text
    df['raw_subject'] = df['subject'].fillna('').astype(str)
    df['raw_description'] = df['description'].fillna('').astype(str)
    df['cleaned_subject'] = df['raw_subject'].apply(clean_text)
    df['cleaned_description'] = df['raw_description'].apply(clean_text)
    df['combined_text'] = (df['cleaned_subject'] + ' ' + df['cleaned_description']).str.strip()
    df['combined_raw'] = (df['raw_subject'] + ' ' + df['raw_description']).str.lower()

    df['word_count'] = df['combined_text'].apply(lambda s: 0 if not s else len(s.split()))

    # Load tagging rules JSON
    try:
        with open(RULES_IN, 'r') as f:
            rules_json = json.load(f)
    except Exception as e:
        data_issues.append(f'Failed to load tagging rules: {e}')
        rules_json = {}

    # Extract rules list
    if isinstance(rules_json, dict):
        if 'tagging_rules' in rules_json and isinstance(rules_json['tagging_rules'], list):
            rules = rules_json['tagging_rules']
        elif 'rules' in rules_json and isinstance(rules_json['rules'], list):
            rules = rules_json['rules']
        else:
            # maybe the JSON itself is a dict of a single rule or empty
            rules = []
    elif isinstance(rules_json, list):
        rules = rules_json
    else:
        rules = []

    # Override question and urgency words if provided
    q_words = set(DEFAULT_QUESTION_WORDS)
    u_words = set(DEFAULT_URGENCY_WORDS)
    if isinstance(rules_json, dict):
        if 'question_words' in rules_json and isinstance(rules_json['question_words'], list):
            q_words = set([str(x).lower() for x in rules_json['question_words'] if x])
        if 'urgency_words' in rules_json and isinstance(rules_json['urgency_words'], list):
            u_words = set([str(x).lower() for x in rules_json['urgency_words'] if x])

    # Ensure rules are sorted by priority ascending (1 is highest)
    try:
        rules = sorted(rules, key=lambda r: int(r.get('priority', 999)))
    except Exception:
        pass

    # contains_question and urgency_indicators
    def contains_question_fn(raw, cleaned):
        if '?' in raw:
            return True
        tokens = set(cleaned.split())
        return any(w in tokens for w in q_words)

    def urgency_count_fn(cleaned):
        if not cleaned:
            return 0
        cnt = 0
        tokens = cleaned.split()
        for u in u_words:
            cnt += tokens.count(u)
        return cnt

    df['contains_question'] = df.apply(lambda r: contains_question_fn(r['combined_raw'], r['combined_text']), axis=1)
    df['urgency_indicators'] = df['combined_text'].apply(urgency_count_fn)

    df['hour_of_day'] = df['created_dt'].dt.hour.fillna(-1).astype(int)

    # Apply rules in priority order
    auto_tags = []
    for _, row in df.iterrows():
        text = row['combined_text']
        matched_tag = None
        for rule in rules:
            if match_rule(rule, text):
                matched_tag = rule.get('tag') or rule.get('name') or ''
                break
        if not matched_tag:
            matched_tag = 'other'
        auto_tags.append(str(matched_tag))

    df['auto_tag'] = auto_tags
    df['manual_tag_filled'] = df['manual_tag'].fillna('').astype(str)
    df['tag_discrepancy'] = (df['manual_tag_filled'].str.strip().str.lower() != df['auto_tag'].str.strip().str.lower())

    # Build final CSV columns: original required columns then new features
    final_cols = []
    for c in REQUIRED_COLS:
        if c in df.columns:
            final_cols.append(c)
    # Add the new required columns
    final_cols += ['cleaned_subject','cleaned_description','word_count','contains_question','urgency_indicators','hour_of_day','auto_tag','tag_discrepancy']

    # Save processed CSV
    df.to_csv(CSV_OUT, columns=final_cols, index=False)

    # Stats
    total = len(df)
    matches = (~df['tag_discrepancy']).sum()
    overall_accuracy = float(matches) / total if total > 0 else 0.0

    def norm_priority(p):
        if pd.isna(p):
            return 'unknown'
        s = str(p).lower().strip()
        if s in ('low', 'l'):
            return 'low'
        if s in ('medium', 'med', 'm'):
            return 'medium'
        if s in ('high', 'h'):
            return 'high'
        return s

    df['priority_norm'] = df['priority'].apply(norm_priority)
    acc_by_priority = {}
    for k in ['low', 'medium', 'high']:
        sub = df[df['priority_norm'] == k]
        if len(sub) == 0:
            acc_by_priority[k] = None
        else:
            acc_by_priority[k] = float((~sub['tag_discrepancy']).sum()) / len(sub)

    discrep = df[df['tag_discrepancy']]
    pairs = list(zip(discrep['manual_tag_filled'].str.strip().str.lower(), discrep['auto_tag'].str.strip().str.lower()))
    counter = Counter(pairs)
    most_common = []
    for (m,a), cnt in counter.most_common(10):
        most_common.append({'manual_tag': m if m!='' else '', 'auto_tag': a if a!='' else '', 'count': int(cnt)})

    # Chi-square
    hours = list(range(24))
    table = []
    for h in hours:
        sub = df[df['hour_of_day'] == h]
        d = int(sub['tag_discrepancy'].sum())
        nd = int(len(sub) - d)
        table.append([d, nd])
    table = np.array(table)

    if chi2_contingency is not None and table.sum() > 0 and table.shape[0] > 1:
        try:
            chi2_stat, p, dof, exp = chi2_contingency(table)
        except Exception:
            chi2_stat, p = 0.0, 1.0
    else:
        chi2_stat, p = 0.0, 1.0

    discrepancy_independent = bool(p > 0.05)

    rates = []
    for h in hours:
        sub = df[df['hour_of_day'] == h]
        if len(sub) == 0:
            continue
        rate = sub['tag_discrepancy'].mean()
        rates.append((h, rate, len(sub)))
    rates_sorted = sorted(rates, key=lambda x: (-x[1], x[0]))
    top3_hours = [int(x[0]) for x in rates_sorted[:3]]

    avg_word_count = float(df['word_count'].mean()) if total>0 else 0.0
    question_percentage = float(df['contains_question'].mean()) if total>0 else 0.0
    urgency_percentage = float((df['urgency_indicators'] > 0).mean()) if total>0 else 0.0

    report = {
        'data_validation': {
            'total_tickets': int(total_tickets),
            'missing_columns': missing_columns,
            'data_issues': data_issues
        },
        'tagging_accuracy': {
            'overall_accuracy': overall_accuracy,
            'accuracy_by_priority': {
                'low': acc_by_priority.get('low'),
                'medium': acc_by_priority.get('medium'),
                'high': acc_by_priority.get('high')
            },
            'most_common_discrepancies': most_common
        },
        'temporal_analysis': {
            'chi2_statistic': float(chi2_stat),
            'chi2_pvalue': float(p),
            'discrepancy_independent': discrepancy_independent,
            'high_discrepancy_hours': top3_hours
        },
        'feature_statistics': {
            'avg_word_count': avg_word_count,
            'question_percentage': question_percentage,
            'urgency_percentage': urgency_percentage
        }
    }

    with open(REPORT_OUT, 'w') as f:
        json.dump(report, f, indent=2)

    # Optional plot
    if plt is not None and len(rates) > 0:
        hours_plot = [r[0] for r in sorted(rates, key=lambda x: x[0])]
        rates_plot = [r[1] for r in sorted(rates, key=lambda x: x[0])]
        plt.figure(figsize=(10,4))
        plt.bar(hours_plot, rates_plot)
        plt.xlabel('Hour of day')
        plt.ylabel('Discrepancy rate')
        plt.title('Discrepancy rate by hour of day')
        plt.xlim(-0.5,23.5)
        plt.ylim(0,1)
        plt.grid(axis='y', alpha=0.3)
        try:
            plt.savefig(PLOT_OUT, bbox_inches='tight')
        except Exception:
            pass

    print('Processing complete. Outputs:')
    print(f' - {CSV_OUT}')
    print(f' - {REPORT_OUT}')
    if PLOT_OUT.exists():
        print(f' - {PLOT_OUT}')

if __name__ == '__main__':
    main()
