#!/usr/bin/env python3
import json
import os
from datetime import datetime, timezone
import math

import pandas as pd
import numpy as np
import yaml

# Paths
TICKETS_CSV = '/app/data/tickets.csv'
TICKET_TEXTS_JSON = '/app/data/ticket_texts.json'
CONFIG_YAML = '/app/config/analysis_rules.yaml'
OUT_DIR = '/app/output'
ENRICHED_CSV = os.path.join(OUT_DIR, 'enriched_tickets.csv')
REPORT_JSON = os.path.join(OUT_DIR, 'analysis_report.json')
OUTLIER_CSV = os.path.join(OUT_DIR, 'outlier_details.csv')

os.makedirs(OUT_DIR, exist_ok=True)

# Load config
with open(CONFIG_YAML, 'r') as f:
    cfg = yaml.safe_load(f)

crit_terms = [t.lower() for t in cfg.get('keywords', {}).get('critical_terms', [])]
common_issues = [t.lower() for t in cfg.get('keywords', {}).get('common_issues', [])]
thresholds = cfg.get('thresholds', {})
iqr_multiplier = float(thresholds.get('resolution_outlier_threshold', 1.5))
min_res_hours = float(thresholds.get('min_resolution_time_hours', 0.1))
max_res_hours = float(thresholds.get('max_resolution_time_hours', 168))

# Load tickets CSV
tickets = pd.read_csv(TICKETS_CSV, dtype={'ticket_id': str}, parse_dates=['created_at', 'resolved_at'], infer_datetime_format=True)
# Ensure columns exist
for col in ['ticket_id', 'created_at', 'resolved_at', 'priority', 'assignee_id']:
    if col not in tickets.columns:
        tickets[col] = pd.NA

# Load ticket texts JSON
with open(TICKET_TEXTS_JSON, 'r') as f:
    texts = json.load(f)
texts_df = pd.DataFrame(texts)
if 'ticket_id' in texts_df.columns:
    texts_df['ticket_id'] = texts_df['ticket_id'].astype(str)
else:
    texts_df['ticket_id'] = pd.NA

# Merge
df = pd.merge(tickets, texts_df, on='ticket_id', how='left')

# Normalize missing columns from texts
if 'subject' not in df.columns:
    df['subject'] = pd.NA
if 'description' not in df.columns:
    df['description'] = ''
if 'tags' not in df.columns:
    df['tags'] = [[] for _ in range(len(df))]

# Ensure tags is list
def normalize_tags(x):
    if isinstance(x, list):
        return [str(t).lower() for t in x]
    if pd.isna(x):
        return []
    # If stored as a string, try to split on comma
    if isinstance(x, str):
        return [t.strip().lower() for t in x.split(',') if t.strip()]
    return []

df['tags'] = df['tags'].apply(normalize_tags)

# Ensure description string
df['description'] = df['description'].fillna('').astype(str)

# Compute resolution_time_hours for resolved tickets
def compute_hours(row):
    ca = row['created_at']
    ra = row['resolved_at']
    if pd.isna(ca):
        return np.nan
    if pd.isna(ra):
        return np.nan
    try:
        delta = ra - ca
        hours = delta.total_seconds() / 3600.0
        return float(hours)
    except Exception:
        return np.nan

df['resolution_time_hours'] = df.apply(compute_hours, axis=1)

# Filter unrealistic resolution times (set to NaN if outside thresholds)
def apply_thresholds(x):
    if pd.isna(x):
        return np.nan
    if x < min_res_hours or x > max_res_hours:
        return np.nan
    return float(x)

df['resolution_time_hours'] = df['resolution_time_hours'].apply(apply_thresholds)

# For unresolved tickets compute age_hours (time since creation)
now = datetime.now(timezone.utc)

def compute_age_hours(row):
    if pd.isna(row['created_at']):
        return np.nan
    if not pd.isna(row['resolved_at']):
        return np.nan
    try:
        # Assume created_at may not be tz-aware
        ca = row['created_at']
        if ca.tzinfo is None:
            ca = ca.replace(tzinfo=timezone.utc)
        delta = now - ca
        return float(delta.total_seconds() / 3600.0)
    except Exception:
        return np.nan

df['age_hours'] = df.apply(compute_age_hours, axis=1)

# Text features
lower_desc = df['description'].str.lower()

def contains_critical(text):
    if not text:
        return False
    for term in crit_terms:
        if term in text:
            return True
    return False

df['contains_critical_term'] = lower_desc.apply(contains_critical)

# contains_common_issue from tags
def contains_common(tags):
    if not tags:
        return False
    for t in tags:
        if t.lower() in common_issues:
            return True
    return False

df['contains_common_issue'] = df['tags'].apply(contains_common)

# word_count
df['word_count'] = df['description'].fillna('').apply(lambda s: len(s.split()))

# Outlier detection using IQR for resolution_time_hours
rt = df['resolution_time_hours'].dropna()
if len(rt) >= 1:
    q1 = rt.quantile(0.25)
    q3 = rt.quantile(0.75)
    iqr = q3 - q1
    if math.isfinite(iqr) and iqr > 0:
        lower = q1 - iqr * iqr_multiplier
        upper = q3 + iqr * iqr_multiplier
    else:
        # If IQR is zero (all values equal) set bounds to wide but no outliers
        lower = -np.inf
        upper = np.inf
else:
    lower = -np.inf
    upper = np.inf

def mark_outlier(x):
    if pd.isna(x):
        return False
    return (x < lower) or (x > upper)

df['is_outlier'] = df['resolution_time_hours'].apply(mark_outlier).astype(bool)

# Build enriched dataframe columns: include all original columns plus required new ones
# Original columns include at least: ticket_id, created_at, resolved_at, priority, assignee_id, subject, description, tags
original_cols = []
for col in ['ticket_id','created_at','resolved_at','priority','assignee_id','subject','description','tags']:
    if col in df.columns:
        original_cols.append(col)

new_cols = ['resolution_time_hours','age_hours','contains_critical_term','contains_common_issue','word_count','is_outlier']

enriched_cols = original_cols + new_cols

enriched_df = df[enriched_cols].copy()

# Ensure boolean columns are real booleans
enriched_df['contains_critical_term'] = enriched_df['contains_critical_term'].astype(bool)
enriched_df['contains_common_issue'] = enriched_df['contains_common_issue'].astype(bool)
enriched_df['is_outlier'] = enriched_df['is_outlier'].astype(bool)

# Save enriched CSV
# For JSON-serializable tags, convert lists to JSON strings in CSV to preserve structure
enriched_df.to_csv(ENRICHED_CSV, index=False)

# Analysis report
report = {}
summary = {}
# Use non-null and non-outlier resolution times for summary statistics
for p in sorted(df['priority'].dropna().unique()):
    try:
        p_int = int(p)
    except Exception:
        p_int = p
    subset = df[(df['priority'] == p) & df['resolution_time_hours'].notnull() & (~df['is_outlier'])]
    if len(subset) == 0:
        summary[f'priority_{p_int}'] = {'mean': None, 'median': None, 'std': None}
    else:
        mean = float(subset['resolution_time_hours'].mean())
        median = float(subset['resolution_time_hours'].median())
        std = float(subset['resolution_time_hours'].std(ddof=0)) if len(subset) > 0 else None
        summary[f'priority_{p_int}'] = {'mean': round(mean, 4), 'median': round(median, 4), 'std': (round(std, 4) if std is not None else None)}

report['summary_statistics'] = summary

# Correlation between word_count and resolution_time_hours (non-null, non-outlier)
corr_df = df[df['resolution_time_hours'].notnull() & (~df['is_outlier']) & df['word_count'].notnull()]
if len(corr_df) >= 2:
    corr_val = corr_df['word_count'].corr(corr_df['resolution_time_hours'])
    if pd.isna(corr_val):
        corr_val = None
    else:
        corr_val = round(float(corr_val), 4)
else:
    corr_val = None

report['correlations'] = {'word_count_vs_resolution': corr_val}

# Top 3 assignees with highest average resolution times (excluding outliers)
assignee_stats = df[df['resolution_time_hours'].notnull() & (~df['is_outlier'])].groupby('assignee_id', dropna=True)['resolution_time_hours'].mean().reset_index()
assignee_stats = assignee_stats.dropna(subset=['assignee_id'])
assignee_stats = assignee_stats.sort_values(by='resolution_time_hours', ascending=False).head(3)
top_slow = []
for _, row in assignee_stats.iterrows():
    top_slow.append({'assignee_id': str(row['assignee_id']), 'avg_resolution_hours': round(float(row['resolution_time_hours']), 4)})

report['top_slow_assignees'] = top_slow

# Anomaly counts
total_outliers = int(df['is_outlier'].sum())
critical_not_p4 = int(((df['contains_critical_term']) & (df['priority'] != 4)).sum())
report['anomaly_counts'] = {'total_outliers': total_outliers, 'critical_not_priority4': critical_not_p4}

# Save report
with open(REPORT_JSON, 'w') as f:
    json.dump(report, f, indent=2)

# Outlier details CSV
outliers = df[df['is_outlier']].copy()
if len(outliers) > 0:
    outliers['reason'] = 'statistical_outlier'
    outlier_details = outliers[['ticket_id','priority','resolution_time_hours','assignee_id','reason']]
    outlier_details.to_csv(OUTLIER_CSV, index=False)
else:
    # Write header-only CSV
    pd.DataFrame(columns=['ticket_id','priority','resolution_time_hours','assignee_id','reason']).to_csv(OUTLIER_CSV, index=False)

print('Processing complete. Files written:')
print(ENRICHED_CSV)
print(REPORT_JSON)
print(OUTLIER_CSV)
