    if re.search(r'\b(billing)\b', desc):
        cat = 'Billing'
    elif re.search(r'\b(login|password)\b', desc):
        cat = 'Access'
    elif re.search(r'\b(slow|lag)\b', desc):
        cat = 'Performance'
    elif re.search(r'\b(error|crash)\b', desc):
        cat = 'Technical'
    else:
        cat = 'General'
    category_counts[cat] += 1

    # Hour
    hour = r['created_at'].hour
