import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
import seaborn as sns

# Paths
DATA_CSV = '/app/data/experiments.csv'
META_JSON = '/app/data/metadata.json'
UNITS_YAML = '/app/config/units_config.yaml'
OUT_CSV = '/app/output/cleaned_experiments.csv'
OUT_JSON = '/app/output/experiment_summary.json'
OUT_PLOT = '/app/output/researcher_boxplot.png'

# Load data
if not os.path.exists(DATA_CSV):
    raise SystemExit(f'Missing data CSV: {DATA_CSV}')
if not os.path.exists(META_JSON):
    raise SystemExit(f'Missing metadata JSON: {META_JSON}')

df = pd.read_csv(DATA_CSV)
with open(META_JSON, 'r') as f:
    meta = json.load(f)

# Build metadata DataFrame
meta_list = meta.get('experiments', [])
meta_df = pd.DataFrame(meta_list)
if 'id' in meta_df.columns:
    meta_df = meta_df.rename(columns={'id': 'experiment_id'})

# Merge
merged = pd.merge(df, meta_df, on='experiment_id', how='left')

# Load units config if present
units_config = {}
if os.path.exists(UNITS_YAML):
    try:
        with open(UNITS_YAML, 'r') as f:
            units_config = yaml.safe_load(f) or {}
    except Exception:
        units_config = {}

# Helpers for unit detection and conversion
def is_temperature_unit(u):
    if pd.isna(u):
        return False
    u = str(u).lower()
    return any(x in u for x in ['c', 'f', 'k', 'kelvin', 'fahrenheit', 'celsius'])

def is_volume_unit(u):
    if pd.isna(u):
        return False
    u = str(u).lower()
    return any(x in u for x in ['l', 'ml', 'µl', 'ul', 'microliter', 'milliliter', 'liter'])

def convert_to_celsius(value, unit):
    if pd.isna(value):
        return np.nan
    try:
        x = float(value)
    except Exception:
        return np.nan
    if pd.isna(unit):
        return x
    u = str(unit).strip().lower()
    if u in ['c', 'celsius', '°c']:
        return x
    if u in ['f', 'fahrenheit', '°f']:
        return (x - 32.0) * 5.0 / 9.0
    if u in ['k', 'kelvin']:
        return x - 273.15
    # fallback: if unit contains 'f' but not 'ml' etc
    if 'f' == u:
        return (x - 32.0) * 5.0 / 9.0
    return x

def convert_to_milliliter(value, unit):
    if pd.isna(value):
        return np.nan
    try:
        x = float(value)
    except Exception:
        return np.nan
    if pd.isna(unit):
        return x
    u = str(unit).strip().lower()
    if u in ['ml', 'milliliter', 'millilitre']:
        return x
    if u in ['l', 'liter', 'litre']:
        return x * 1000.0
    if u in ['ul', 'µl', 'microliter', 'microlitre']:
        return x * 0.001
    # fallback
    return x

# Flag units and convert
merged['unit_flag'] = False
merged['converted_value'] = np.nan
merged['converted_unit'] = None

# Determine expected units from config if available
expected_temp_units = None
expected_vol_units = None
if isinstance(units_config, dict):
    expected_temp_units = units_config.get('temperature_expected_units') or units_config.get('temperature')
    expected_vol_units = units_config.get('volume_expected_units') or units_config.get('volume')

for idx, row in merged.iterrows():
    unit = row.get('unit')
    value = row.get('measurement')

    if is_temperature_unit(unit):
        # flag mismatch if config provided and unit not in expected list
        if expected_temp_units:
            # normalize expected to list
            if isinstance(expected_temp_units, str):
                exp_list = [expected_temp_units.lower()]
            elif isinstance(expected_temp_units, (list, tuple)):
                exp_list = [str(x).lower() for x in expected_temp_units]
            else:
                exp_list = []
            if str(unit).lower() not in exp_list:
                merged.at[idx, 'unit_flag'] = True
        merged.at[idx, 'converted_value'] = convert_to_celsius(value, unit)
        merged.at[idx, 'converted_unit'] = 'C'
    elif is_volume_unit(unit):
        if expected_vol_units:
            if isinstance(expected_vol_units, str):
                exp_list = [expected_vol_units.lower()]
            elif isinstance(expected_vol_units, (list, tuple)):
                exp_list = [str(x).lower() for x in expected_vol_units]
            else:
                exp_list = []
            if str(unit).lower() not in exp_list:
                merged.at[idx, 'unit_flag'] = True
        merged.at[idx, 'converted_value'] = convert_to_milliliter(value, unit)
        merged.at[idx, 'converted_unit'] = 'mL'
    else:
        # Unknown unit category: leave converted_value as numeric measurement if possible
        try:
            merged.at[idx, 'converted_value'] = float(value)
            merged.at[idx, 'converted_unit'] = row.get('unit')
        except Exception:
            merged.at[idx, 'converted_value'] = np.nan
            merged.at[idx, 'converted_unit'] = row.get('unit')
            merged.at[idx, 'unit_flag'] = True

# Parse timestamp and add weekday/weekend
def parse_timestamp(ts):
    if pd.isna(ts):
        return None
    # try common formats
    for fmt in ['%Y-%m-%dT%H:%M:%S', '%Y-%m-%d %H:%M:%S', '%Y-%m-%d']:
        try:
            return datetime.strptime(str(ts), fmt)
        except Exception:
            continue
    try:
        return pd.to_datetime(ts)
    except Exception:
        return None

merged['parsed_ts'] = merged['timestamp'].apply(parse_timestamp)
merged['is_weekend'] = merged['parsed_ts'].apply(lambda d: d.weekday() >= 5 if d is not None else False)

# Remove any experiments where researcher is missing in metadata
cleaned = merged.dropna(subset=['researcher']).copy()

# Ensure converted_value numeric
cleaned['converted_value'] = pd.to_numeric(cleaned['converted_value'], errors='coerce')

# Compute per-experiment stats
group = cleaned.groupby('experiment_id')
stats_df = group['converted_value'].agg(['mean', 'median', 'std', 'count']).reset_index()
stats_df['cv_percent'] = (stats_df['std'] / stats_df['mean']).abs() * 100.0
stats_df['qc_pass'] = (stats_df['cv_percent'] < 15.0) & (stats_df['count'] >= 5)

# Merge stats back to cleaned rows
cleaned = cleaned.merge(stats_df[['experiment_id', 'mean', 'median', 'std', 'count', 'cv_percent', 'qc_pass']], on='experiment_id', how='left')

# Outlier detection per experiment using IQR
def mark_outliers(subdf):
    vals = subdf['converted_value'].dropna()
    if vals.empty:
        return pd.Series([False]*len(subdf), index=subdf.index)
    q1 = vals.quantile(0.25)
    q3 = vals.quantile(0.75)
    iqr = q3 - q1
    lower = q1 - 1.5 * iqr
    upper = q3 + 1.5 * iqr
    return ~subdf['converted_value'].between(lower, upper)

cleaned['is_outlier'] = cleaned.groupby('experiment_id', group_keys=False).apply(mark_outliers)

# Per-researcher ANOVA (use converted_value)
researcher_groups = cleaned.groupby('researcher')['converted_value'].apply(lambda s: s.dropna().values)
# Remove empty groups
researcher_groups = [v for v in researcher_groups if len(v) > 0]
anova_p = None
significant = False
if len(researcher_groups) >= 2:
    try:
        fstat, anova_p = stats.f_oneway(*researcher_groups)
    except Exception:
        anova_p = None
if anova_p is None:
    anova_p = float('nan')
else:
    significant = bool(anova_p < 0.05)

# Cohen's d between top-performing and bottom-performing researchers (by mean)
researcher_means = cleaned.groupby('researcher')['converted_value'].mean().dropna()
effect_size = float('nan')
if len(researcher_means) >= 2:
    top = researcher_means.idxmax()
    bottom = researcher_means.idxmin()
    top_vals = cleaned.loc[cleaned['researcher'] == top, 'converted_value'].dropna()
    bottom_vals = cleaned.loc[cleaned['researcher'] == bottom, 'converted_value'].dropna()
    # pooled std
    nx = len(top_vals)
    ny = len(bottom_vals)
    if nx > 1 and ny > 1:
        sx = top_vals.std(ddof=1)
        sy = bottom_vals.std(ddof=1)
        pooled = np.sqrt(((nx - 1) * sx ** 2 + (ny - 1) * sy ** 2) / (nx + ny - 2))
        if pooled > 0:
            effect_size = (top_vals.mean() - bottom_vals.mean()) / pooled
            effect_size = abs(effect_size)
        else:
            effect_size = 0.0
    else:
        # fallback: compute with population std
        try:
            pooled = np.sqrt(top_vals.var() + bottom_vals.var())
            effect_size = abs(top_vals.mean() - bottom_vals.mean()) / pooled if pooled > 0 else float('nan')
        except Exception:
            effect_size = float('nan')

# Identify 3 most consistent experiments (lowest CV)
top3 = stats_df.dropna(subset=['cv_percent']).nsmallest(3, 'cv_percent')['experiment_id'].tolist()

# Weekend vs weekday analysis
weekday_vals = cleaned.loc[~cleaned['is_weekend'], 'converted_value'].dropna()
weekend_vals = cleaned.loc[cleaned['is_weekend'], 'converted_value'].dropna()
weekday_mean = float(weekday_vals.mean()) if len(weekday_vals) > 0 else float('nan')
weekend_mean = float(weekend_vals.mean()) if len(weekend_vals) > 0 else float('nan')
weekend_p = float('nan')
if len(weekday_vals) >= 2 and len(weekend_vals) >= 2:
    try:
        tstat, weekend_p = stats.ttest_ind(weekday_vals, weekend_vals, equal_var=False, nan_policy='omit')
    except Exception:
        weekend_p = float('nan')

# Summary JSON
total_experiments = int(stats_df['experiment_id'].nunique())
quality_pass_rate = float((stats_df['qc_pass'].sum()) / max(1, len(stats_df)))

summary = {
    "total_experiments": total_experiments,
    "quality_pass_rate": round(quality_pass_rate, 6),
    "researcher_comparison": {
        "anova_p_value": (None if (anova_p is None or (isinstance(anova_p, float) and np.isnan(anova_p))) else float(anova_p)),
        "significant_difference": bool(significant),
        "effect_size": (None if (isinstance(effect_size, float) and np.isnan(effect_size)) else float(effect_size))
    },
    "top_performers": top3,
    "weekend_effect": {
        "weekday_mean": (None if (isinstance(weekday_mean, float) and np.isnan(weekday_mean)) else float(weekday_mean)),
        "weekend_mean": (None if (isinstance(weekend_mean, float) and np.isnan(weekend_mean)) else float(weekend_mean)),
        "p_value": (None if (isinstance(weekend_p, float) and np.isnan(weekend_p)) else float(weekend_p))
    }
}

# Save cleaned CSV
os.makedirs(os.path.dirname(OUT_CSV), exist_ok=True)
cleaned.to_csv(OUT_CSV, index=False)

# Save JSON ensuring exact keys exist and numeric types used where possible
with open(OUT_JSON, 'w') as f:
