for y in years_in_csv:
    if y < 2018 or y > 2024:
        errors.append(f'Year {y} in CSV outside allowed range')

# Final outcome
if errors:
    print('VALIDATION FAILED')
    for e in errors:
        print('- ' + str(e))
    sys.exit(1)
else:
    print('VALIDATION PASSED: All checks OK. CSV and summary look consistent.')
    sys.exit(0)
