import csv
import gc

def load_data(path):
    """Load sensor data from CSV. Returns a list of dicts: {'timestamp': str, 'value': float}
    Uses context manager to ensure file handles are closed and returns fresh lists (prevents leaks).
    """
    data = []
    try:
        with open(path, newline='') as f:
            reader = csv.DictReader(f)
            for row in reader:
                # normalize keys and parse numeric 'value' field
                ts = row.get('timestamp') or row.get('time') or row.get('ts')
                if ts is None:
                    continue
                try:
                    val = float(row.get('value') or row.get('reading') or 0.0)
                except Exception:
                    # skip bad rows
                    continue
                data.append({'timestamp': str(ts), 'value': val})
    except FileNotFoundError:
        return []
    finally:
        # encourage freeing resources
        gc.collect()
    return data

if __name__ == '__main__':
    import sys
    print(load_data(sys.argv[1] if len(sys.argv) > 1 else '/app/data/sensors.csv'))
