import threading

_lock = threading.Lock()

def apply_transformations(data, transformations):
    """Apply list of transformations to data in parallel threads.
    Each transformation is a dict with a 'name' key (e.g., 'scale', 'offset').
    Uses a lock to protect writing into shared result array to avoid race conditions.
    Returns a new list of transformed records.
    """
    if not data:
        return []
    results = [None] * len(data)

    def worker(i, record):
        val = float(record.get('value', 0.0))
        for t in transformations:
            name = t.get('name') if isinstance(t, dict) else None
            if name == 'scale':
                try:
                    factor = float(t.get('factor', 1.0))
                except Exception:
                    factor = 1.0
                val = val * factor
            elif name == 'offset':
                try:
                    off = float(t.get('value', 0.0))
                except Exception:
                    off = 0.0
                val = val + off
            # extendable: add other transforms here
        newrec = {'timestamp': record.get('timestamp'), 'value': val}
        # protect writing to shared results
        with _lock:
            results[i] = newrec

    threads = []
    for i, rec in enumerate(data):
        th = threading.Thread(target=worker, args=(i, rec))
        th.start()
        threads.append(th)
    for th in threads:
        th.join()

    # filter out any None (shouldn't happen) and return list
    return [r for r in results if r is not None]

if __name__ == '__main__':
