from collections import defaultdict
import datetime
import json

def _parse_timestamp_to_hour(ts):
    # try ISO format first, then epoch seconds
    try:
        dt = datetime.datetime.fromisoformat(ts)
    except Exception:
        try:
            dt = datetime.datetime.fromtimestamp(float(ts))
        except Exception:
            return None
    hour = dt.replace(minute=0, second=0, microsecond=0)
    return hour.isoformat()


def aggregate_by_hour(data):
    """Aggregate records by hour. Expects records with 'timestamp' and numeric 'value'.
    Returns list of dicts: {'hour': <iso hour>, 'avg_value': float, 'max_value': float}
    Numeric values are rounded to 2 decimals.
    """
    buckets = defaultdict(list)
    for r in data:
        ts = r.get('timestamp')
        if ts is None:
            continue
        hour = _parse_timestamp_to_hour(str(ts))
        if hour is None:
            continue
        try:
            v = float(r.get('value', 0.0))
        except Exception:
            continue
        buckets[hour].append(v)

    aggs = []
    for hour in sorted(buckets.keys()):
        vals = buckets[hour]
        if not vals:
            continue
        avg = sum(vals) / len(vals)
        mx = max(vals)
        # ensure floats with 2 decimal places
        aggs.append({'hour': hour, 'avg_value': round(float(avg), 2), 'max_value': round(float(mx), 2)})
    return aggs


def write_output(output_path, total_records, processing_time_ms, aggs, errors):
    """Write output JSON with required top-level keys: summary, aggregations, errors.
    All numeric values are floats rounded to 2 decimals.
    """
    summary = {
        'total_records': float(round(float(total_records), 2)),
        'processing_time_ms': float(round(float(processing_time_ms), 2)),
        'status': 'ok' if not errors else 'error'
    }
    out = {
        'summary': summary,
        'aggregations': aggs,
        'errors': errors if isinstance(errors, list) else [str(errors)]
    }
    # ensure directory exists
    import os
    d = os.path.dirname(output_path)
    if d and not os.path.exists(d):
        os.makedirs(d, exist_ok=True)
    with open(output_path, 'w') as f:
        json.dump(out, f, indent=2)
    return out

if __name__ == '__main__':
    # quick local test
    sample = [{'timestamp': '2020-01-01T00:10:00', 'value': 1.234}, {'timestamp': '2020-01-01T00:20:00', 'value': 2.345}]
    ag = aggregate_by_hour(sample)
    print(ag)
    write_output('/tmp/results.json', len(sample), 12.34, ag, [])
