import time
import gc
import tracemalloc
import json

from data_loader import load_data
from transformer import apply_transformations
from aggregator import aggregate_by_hour, write_output


def load_config(path):
    # try yaml if available, fallback to simple parser
    try:
        import yaml
        with open(path) as f:
            cfg = yaml.safe_load(f)
            return cfg or {}
    except Exception:
        cfg = {}
        try:
            with open(path) as f:
                current_key = None
                for line in f:
                    line = line.strip()
                    if not line or line.startswith('#'):
                        continue
                    if line.startswith('- '):
                        # simple list item: append to 'transformations'
                        val = line[2:].strip()
                        if 'transformations' not in cfg:
                            cfg['transformations'] = []
                        # naive parse of key: value
                        if ':' in val:
                            k,v = val.split(':',1)
                            cfg['transformations'].append({k.strip(): v.strip().strip('"').strip("'")})
                        else:
                            cfg['transformations'].append(val)
                        continue
                    if ':' in line:
                        k,v = line.split(':',1)
                        cfg[k.strip()] = v.strip().strip('"').strip("'")
        except Exception:
            pass
        # ensure expected keys exist
        if 'transformations' not in cfg:
            cfg['transformations'] = []
        return cfg


def validate_config(cfg):
    required = ['input_path', 'output_path', 'transformations', 'aggregation_window']
    for k in required:
        if k not in cfg or cfg[k] is None:
            raise RuntimeError(f'Missing required config key: {k}')


def main():
    cfg = load_config('/app/config/pipeline.yaml')
    try:
        validate_config(cfg)
    except Exception as e:
        print('Configuration error:', e)
        raise

    tracemalloc.start()
    start_snap = tracemalloc.take_snapshot()
    start_time = time.time()

    data = load_data(cfg['input_path'])
    # ensure transformations is a list of dicts; best effort coercion
    trans = cfg.get('transformations') or []
    # normalize transforms to list of dicts
    normal_trans = []
    for t in trans:
        if isinstance(t, dict):
            normal_trans.append(t)
        elif isinstance(t, str):
            # simple name -> no-op or default
            normal_trans.append({'name': t})
    # apply transformations (thread-safe in transformer.apply_transformations)
    transformed = apply_transformations(data, normal_trans)

    # aggregate
    aggs = aggregate_by_hour(transformed)

    processing_time_ms = (time.time() - start_time) * 1000.0
    total_records = len(transformed)
    errors = []

    # write output with required schema
    write_output(cfg['output_path'], total_records, processing_time_ms, aggs, errors)

    # cleanup and memory report
    del data
    del transformed
    gc.collect()
    end_snap = tracemalloc.take_snapshot()
    top_stats = end_snap.compare_to(start_snap, 'lineno')
    print('Top 5 memory differences:')
    for stat in top_stats[:5]:
        print(stat)
    tracemalloc.stop()
    print('Pipeline complete. Records:', total_records, 'Processing time ms:', round(processing_time_ms,2))

if __name__ == '__main__':
    main()
