    if src.exists():
        shutil.copy2(src, APP / (p + '.bak'))
        log.append(f'Backed up {p} to {p}.bak')

# -- Fix requirements: produce requirements_fixed.txt by stripping version pins
req_in = APP / 'requirements.txt'
req_out = APP / 'requirements_fixed.txt'
reqs = []
if req_in.exists():
    for line in req_in.read_text().splitlines():
        s = line.strip()
        if not s or s.startswith('#'):
            continue
        # take part before comparison operators
        name = re.split(r'[<>=!~]', s, 1)[0].strip()
        # keep extras (pkg[extra]) as-is, strip environment markers
        name = name.split(';',1)[0].strip()
        if name:
            reqs.append(name)
    if reqs:
        req_out.write_text('\n'.join(reqs) + '\n')
        log.append(f'Wrote {len(reqs)} entries to requirements_fixed.txt')
    else:
        req_out.write_text('')
        log.append('No requirements parsed; wrote empty requirements_fixed.txt')
else:
    log.append('No requirements.txt found')

# -- Soft-patch setup.py: remove or clear install_requires to avoid forcing conflicting versions
setup_py = APP / 'setup.py'
if setup_py.exists():
    s = setup_py.read_text()
    # Try to replace install_requires=[...] with install_requires=[]
    new_s, n = re.subn(r"install_requires\s*=\s*\[.*?\]", "install_requires=[]", s, flags=re.S)
    if n:
        setup_py.write_text(new_s)
        log.append(f'Patched setup.py: replaced install_requires (occurrences: {n})')
    else:
        # try an alternate pattern inside setup(...) call; if not found, append an explicit install_requires
        if 'setup(' in s and 'install_requires' not in s:
            # insert install_requires=[] into setup(...) call arguments by a simple heuristic
            new_s = s.replace('setup(', 'setup(install_requires=[], ', 1)
            setup_py.write_text(new_s)
            log.append('Patched setup.py: inserted install_requires=[] into setup()')
        else:
            log.append('setup.py: no install_requires pattern found and no change made')
else:
    log.append('No setup.py found to patch')

# -- Fix config.json using heuristic text fixes
cfg_in = APP / 'config.json'
cfg_out = APP / 'config_fixed.json'
config_data = None
if cfg_in.exists():
    raw = cfg_in.read_text()
    # Try direct load first
    try:
        config_data = json.loads(raw)
        log.append('config.json parsed as valid JSON initially')
    except Exception as e:
        log.append(f'Initial json.loads failed: {e}')
        t = raw
        # remove // and # style comments
        t = re.sub(r'(?m)//.*$|(?m)#.*$', '', t)
        # remove trailing commas before } or ]
        t = re.sub(r',\s*([}\]])', r'\1', t)
        # add quotes to unquoted keys: { key:  -> {"key":
        t = re.sub(r'([\{,\[]\s*)([A-Za-z_][A-Za-z0-9_]*)\s*:', r"\1\"\2\":", t)
        # try to load
        try:
            config_data = json.loads(t)
            log.append('config.json repaired by regex heuristics and parsed')
        except Exception as e2:
            log.append(f'After heuristics json.loads still failed: {e2}')
            # last resort: attempt ast.literal_eval
            try:
                import ast
                config_data = ast.literal_eval(t)
                log.append('config.json parsed via ast.literal_eval')
            except Exception as e3:
                log.append(f'Failed to parse config.json by ast.literal_eval: {e3}')
                config_data = None

    # If we have config_data, validate against schema and fill missing required fields
    if config_data is not None:
        schema_path = APP / 'schema.json'
        try:
            schema = json.loads(schema_path.read_text())
        except Exception as sx:
            schema = None
            log.append(f'Failed to read schema.json: {sx}')
        if schema:
            # lazy import jsonschema; if not installed, raise and let outer environment install it
            try:
                import jsonschema
                from jsonschema import validate
                validate(instance=config_data, schema=schema)
                log.append('config.json validated against schema without changes')
            except Exception as ve:
                log.append(f'Validation error (or jsonschema missing): {ve}')
                # If ValidationError due to missing required keys, try to fill them
                try:
                    reqs = schema.get('required', [])
                    props = schema.get('properties', {})
                    changed = False
                    for k in reqs:
                        if k not in config_data:
                            p = props.get(k, {})
                            t = p.get('type')
                            if t == 'string':
                                config_data[k] = p.get('default', '')
                            elif t == 'number' or t == 'integer':
                                config_data[k] = p.get('default', 0)
                            elif t == 'boolean':
                                config_data[k] = p.get('default', False)
                            elif t == 'object':
                                config_data[k] = p.get('default', {})
                            elif t == 'array':
                                config_data[k] = p.get('default', [])
                            else:
                                config_data[k] = p.get('default', None)
                            changed = True
                            log.append(f'Inserted placeholder for missing required key: {k}')
                    if changed:
