                except Exception as eF:
                    log.append(f'Error while attempting to fill schema required fields: {eF}')
        # write config_fixed.json
        try:
            cfg_out.write_text(json.dumps(config_data, indent=2))
            log.append('Wrote config_fixed.json')
        except Exception as ew:
            log.append(f'Failed to write config_fixed.json: {ew}')
else:
    log.append('No config.json found')

# Final log dump to file
with open(APP / 'debug_log.txt', 'a') as f:
    f.write('\n==== Automated fixer run ====' + '\n')
    for L in log:
        f.write(L + '\n')
print('\n'.join(log))
