#!/usr/bin/env python3
"""
Robust dependency resolver.
Supports input formats:
- {"package": ["==1.2.3", ">=1.0"] , ...}
- {"package": {"constraints": [...], "available_versions": [...]}, ...}

Behavior:
- Uses packaging for Version and SpecifierSet.
- If available_versions provided, picks highest compatible version.
- If no available_versions, requires exact '==' constraint(s) to choose a version.
- Outputs /app/resolved_versions.json with mapping or {"error": "..."}.
- Writes clear messages to stderr on invalid inputs.
"""
import json
import sys
from pathlib import Path

try:
    from packaging.version import Version, InvalidVersion
    from packaging.specifiers import SpecifierSet, InvalidSpecifier
except Exception as e:
    print("The 'packaging' library is required. Install with: pip install packaging", file=sys.stderr)
    raise

IN_PATH = Path('/app/constraints.json')
OUT_PATH = Path('/app/resolved_versions.json')


def load_constraints(path: Path):
    try:
        with path.open('r') as f:
            data = json.load(f)
    except Exception as e:
        raise RuntimeError(f"Failed to read/parse {path}: {e}")
    if not isinstance(data, dict):
        raise RuntimeError("constraints.json must be a JSON object mapping package names to constraints")
    return data


def normalize_package_entry(value):
    # Return (spec_list, available_versions_list_or_None)
    if isinstance(value, list):
        return value, None
    if isinstance(value, dict):
        specs = []
        if 'constraints' in value:
            if not isinstance(value['constraints'], list):
                raise RuntimeError("'constraints' must be a list")
            specs = value['constraints']
        elif 'specs' in value:
            if not isinstance(value['specs'], list):
                raise RuntimeError("'specs' must be a list")
            specs = value['specs']
        else:
            # If dict directly maps versions to something, try to be permissive
            if 'available_versions' not in value:
                # empty constraints
                specs = []
        av = None
        if 'available_versions' in value:
            if not isinstance(value['available_versions'], list):
                raise RuntimeError("'available_versions' must be a list")
            av = value['available_versions']
        return specs, av
    if isinstance(value, str):
        return [value], None
    raise RuntimeError('Each package entry must be a list, dict, or string')


def parse_specifier_list(specs):
    # Combine multiple specifiers into a single SpecifierSet (comma-separated)
    if not specs:
        return SpecifierSet()
    if not isinstance(specs, list):
        raise RuntimeError('Expected list of specifier strings')
    combined = ','.join(s.strip() for s in specs if s is not None)
    try:
        return SpecifierSet(combined)
    except InvalidSpecifier as e:
        raise RuntimeError(f'Invalid specifier in list {specs}: {e}')


def choose_version_from_available(av_list, spec_set):
    # Filter available versions and pick the highest Version
    candidates = []
    for v in av_list:
        try:
            vv = Version(str(v))
        except InvalidVersion:
            # skip invalid versions but warn
            print(f"Warning: skipping invalid available_versions entry: {v}", file=sys.stderr)
            continue
        if vv in spec_set:
            candidates.append(vv)
    if not candidates:
        return None
    best = max(candidates)
    return str(best)


def find_exact_from_specs(specs):
    # If there is at least one '==' spec, ensure they don't conflict and return that value
    eqs = []
    for s in specs:
        s = s.strip()
        if s.startswith('=='):
            eqs.append(s[2:])
        # also accept '===' (rare) as exact
        if s.startswith('==='):
            eqs.append(s[3:])
    if not eqs:
        return None
    # Ensure all equalities agree
    try:
        versions = [str(Version(x)) for x in eqs]
    except InvalidVersion as e:
        raise RuntimeError(f'Invalid exact version in equality specifiers: {e}')
    if len(set(versions)) != 1:
        raise RuntimeError(f'Conflicting exact version constraints: {versions}')
    return versions[0]


def main():
    try:
        data = load_constraints(IN_PATH)
    except Exception as e:
        print(str(e), file=sys.stderr)
        OUT_PATH.write_text(json.dumps({"error": f"Failed to load constraints: {e}"}))
        sys.exit(1)

    resolved = {}
    try:
        for pkg, entry in data.items():
            try:
                specs, available = normalize_package_entry(entry)
            except RuntimeError as re:
                raise RuntimeError(f"Package '{pkg}': {re}")

            # parse specifier set
            try:
                specset = parse_specifier_list(specs)
            except RuntimeError as re:
                raise RuntimeError(f"Package '{pkg}': {re}")

            # If available_versions provided, use them to pick the highest compatible version
            if available is not None:
                ver = choose_version_from_available(available, specset)
                if ver is None:
                    raise RuntimeError(f"Package '{pkg}': no available_versions satisfy constraints {specs}")
                resolved[pkg] = ver
                continue

            # If no available_versions provided, look for exact '==' constraints
            exact = find_exact_from_specs(specs)
            if exact is not None:
                # validate exact matches specset (should by definition)
                try:
                    if Version(exact) not in specset and str(specset) != '':
                        # If specset is not empty and exact doesn't match, it's a conflict
                        raise RuntimeError(f"Package '{pkg}': exact version {exact} does not satisfy other constraints {specs}")
                except InvalidVersion:
                    raise RuntimeError(f"Package '{pkg}': invalid exact version {exact}")
                resolved[pkg] = exact
                continue

            # No available versions and no exact versions -> cannot determine concrete version
            raise RuntimeError(f"Package '{pkg}': no available_versions provided and constraints {specs} do not include an exact '==' version; cannot choose a version deterministically")

    except RuntimeError as e:
        msg = str(e)
        print('Error during resolution:', msg, file=sys.stderr)
        OUT_PATH.write_text(json.dumps({"error": msg}))
        sys.exit(1)

    # write resolved mapping
    try:
        OUT_PATH.write_text(json.dumps(resolved, indent=2))
        print(f"Wrote resolved versions to {OUT_PATH}")
    except Exception as e:
        print(f"Failed to write output: {e}", file=sys.stderr)
        sys.exit(1)


if __name__ == '__main__':
    main()
PY
