DEPENDENCIES: Dict[str, List[Tuple[str, str]]] = {
    "pandas": [("numpy", ">=1.20.0")],
    "scikit-learn": [("numpy", ">=1.19.0")],
    "tensorflow": [("numpy", ">=1.19.0")],
    "torch": [("numpy", ">=1.21.0")]
}


def load_constraints(path: Path) -> Tuple[Dict[str, SpecifierSet], Dict[str, List[str]]]:
    try:
        raw = json.loads(path.read_text())
    except Exception as e:
        raise RuntimeError(f"Failed to read/parse {path}: {e}")
    if not isinstance(raw, dict):
        raise RuntimeError("constraints.json must be a JSON object mapping package names to constraints")

    specs: Dict[str, SpecifierSet] = {}
    input_avails: Dict[str, List[str]] = {}

    for pkg, entry in raw.items():
        # entry can be string, list, or dict
        if isinstance(entry, str):
            spec_text = entry.strip()
            try:
                specs[pkg] = SpecifierSet(spec_text)
            except InvalidSpecifier as e:
                raise RuntimeError(f"Package '{pkg}': invalid specifier string: {e}")
        elif isinstance(entry, list):
            # join list into comma-separated specifier string
            try:
                spec_text = ','.join(s.strip() for s in entry)
                specs[pkg] = SpecifierSet(spec_text)
            except InvalidSpecifier as e:
                raise RuntimeError(f"Package '{pkg}': invalid specifier list: {e}")
        elif isinstance(entry, dict):
            # expect optional 'constraints' list or 'specs' and optional 'available_versions'
            if 'constraints' in entry:
                if not isinstance(entry['constraints'], list):
                    raise RuntimeError(f"Package '{pkg}': 'constraints' must be a list")
                try:
                    spec_text = ','.join(s.strip() for s in entry['constraints'])
                    specs[pkg] = SpecifierSet(spec_text)
                except InvalidSpecifier as e:
                    raise RuntimeError(f"Package '{pkg}': invalid constraints list: {e}")
            else:
                # no constraints field => empty SpecifierSet (allow all)
                specs[pkg] = SpecifierSet()

            if 'available_versions' in entry:
                if not isinstance(entry['available_versions'], list):
                    raise RuntimeError(f"Package '{pkg}': 'available_versions' must be a list")
                input_avails[pkg] = [str(v) for v in entry['available_versions']]
        else:
            raise RuntimeError(f"Package '{pkg}': invalid constraint entry type: {type(entry)}")

    return specs, input_avails


class Resolver:
    def __init__(self, specs: Dict[str, SpecifierSet], input_avails: Dict[str, List[str]]):
        self.specs = specs
        self.input_avails = input_avails
        # combine package universe: from defaults and from input
        self.packages = set(AVAILABLE_VERSIONS.keys()) | set(specs.keys()) | set(input_avails.keys())
        # prepare available_versions per package (sorted descending by Version so we try highest first)
        self.available_versions: Dict[str, List[str]] = {}
        for pkg in self.packages:
            if pkg in input_avails:
                lst = input_avails[pkg]
            else:
                lst = AVAILABLE_VERSIONS.get(pkg, [])
            # filter out invalid version strings and sort descending
            parsed = []
            for v in lst:
                try:
                    parsed.append(Version(str(v)))
                except InvalidVersion:
                    print(f"Warning: ignoring invalid version '{v}' for package '{pkg}'", file=sys.stderr)
            parsed.sort(reverse=True)
            self.available_versions[pkg] = [str(v) for v in parsed]

    def version_satisfies(self, version: str, spec: SpecifierSet) -> bool:
        try:
            v = Version(version)
            # standard membership check; SpecifierSet handles prereleases per PEP 440
            return v in spec
        except InvalidVersion:
            return False

    def find_or_assign(self) -> Dict[str, str]:
        assignment: Dict[str, str] = {}
        # try to resolve every package
        for pkg in sorted(self.packages):
            if pkg in assignment:
                continue
            success = self._find_compatible_version(pkg, assignment, visiting=set())
            if not success:
                raise RuntimeError(f"No solution found while resolving package '{pkg}'")
        return assignment

    def _find_compatible_version(self, pkg: str, assignment: Dict[str, str], visiting: Set[str]) -> bool:
        if pkg in assignment:
            return True
        if pkg in visiting:
            # cycle detected; fail resolution for this path
            return False
        visiting.add(pkg)

        # obtain the specifier for this package (default allow all)
        pkg_spec = self.specs.get(pkg, SpecifierSet())

        candidates = self.available_versions.get(pkg, [])
        if not candidates:
            # If there are no available versions, but there is an exact '==' in spec, accept that exact value
            # Attempt to detect '==' exact in original input spec string
            # We don't have original raw text here beyond SpecifierSet; so fail deterministically
            visiting.remove(pkg)
            return False

        # Try candidates highest-first
        for cand in candidates:
            if not self.version_satisfies(cand, pkg_spec):
                continue
            # tentatively assign
            assignment[pkg] = cand
            ok = True
            # check dependencies of this package
            deps = DEPENDENCIES.get(pkg, [])
            for dep_name, dep_constraint in deps:
                # ensure dependency also respects its own spec and this dep_constraint
                # build a combined specifier: dep's own spec (if any) AND dep_constraint
                own_spec = self.specs.get(dep_name, SpecifierSet())
                try:
                    combined_spec = SpecifierSet(','.join([str(own_spec), dep_constraint]))
                except InvalidSpecifier:
                    # fallback: check separately
                    combined_spec = own_spec
                # If dep already assigned, check it
                if dep_name in assignment:
                    if not self.version_satisfies(assignment[dep_name], combined_spec):
                        ok = False
                        break
                    else:
                        continue
                # else attempt to resolve dep with the combined constraint temporarily
                # Save current spec to restore after recursion
                prev_spec = self.specs.get(dep_name)
                # intersect by creating a new SpecifierSet representing both; SpecifierSet has no direct intersection method
                # we'll set a temporary spec that is comma-joined of existing and new
                try:
                    new_spec = SpecifierSet(','.join([str(self.specs.get(dep_name, SpecifierSet())), dep_constraint]))
                except InvalidSpecifier:
                    new_spec = self.specs.get(dep_name, SpecifierSet())
                self.specs[dep_name] = new_spec
                resolved = self._find_compatible_version(dep_name, assignment, visiting)
                # restore original spec
                if prev_spec is None:
                    self.specs.pop(dep_name, None)
                else:
                    self.specs[dep_name] = prev_spec
                if not resolved:
                    ok = False
                    break
                # finally, ensure assigned dep satisfies the dep_constraint
                if not self.version_satisfies(assignment[dep_name], SpecifierSet(dep_constraint)):
                    ok = False
                    break
            if ok:
                visiting.remove(pkg)
                return True
            # otherwise backtrack assignment and try next candidate
            assignment.pop(pkg, None)
        visiting.remove(pkg)
        return False


def main():
    try:
        specs, input_avails = load_constraints(IN_PATH)
    except Exception as e:
        msg = f"Error loading constraints: {e}"
        print(msg, file=sys.stderr)
        OUT_PATH.write_text(json.dumps({"error": msg}))
        sys.exit(1)

    resolver = Resolver(specs, input_avails)
    try:
        assignment = resolver.find_or_assign()
    except Exception as e:
        msg = str(e)
        print('Error during resolution:', msg, file=sys.stderr)
        OUT_PATH.write_text(json.dumps({"error": msg}))
        sys.exit(1)

    # success
    try:
        OUT_PATH.write_text(json.dumps(assignment, indent=2))
        print(f"Wrote resolved versions to {OUT_PATH}")
    except Exception as e:
        print(f"Failed to write output: {e}", file=sys.stderr)
        sys.exit(1)

if __name__ == '__main__':
    main()
