#!/usr/bin/env python3
import json
import sys
from packaging.version import Version, InvalidVersion
from packaging.specifiers import SpecifierSet, InvalidSpecifier

def err(msg):
    print(msg, file=sys.stderr)

def load_constraints(path='/app/constraints.json'):
    try:
        with open(path) as f:
            data = json.load(f)
    except Exception as e:
        err(f"Failed to load constraints file: {e}")
        return None
    if not isinstance(data, dict):
        err("constraints.json must be a JSON object mapping package names to constraints")
        return None
    return data

def normalize_constraints(data):
    constraints_map = {}
    avail_map = {}
    deps_map = {}
    for pkg, info in data.items():
        if not isinstance(info, dict):
            err(f"Package {pkg} entry must be an object")
            return None, None, None
        constraints = info.get('constraints', [])
        if isinstance(constraints, str):
            constraints = [constraints]
        if not isinstance(constraints, list):
            err(f"{pkg}: 'constraints' must be a list or string")
            return None, None, None
        constraints_map.setdefault(pkg, [])
        for c in constraints:
            if not isinstance(c, str):
                err(f"{pkg}: constraint {c} is not a string")
                return None, None, None
            constraints_map[pkg].append(c.strip())
        av = info.get('available_versions')
        if av is None:
            err(f"{pkg}: 'available_versions' key missing")
            return None, None, None
        if not isinstance(av, list):
            err(f"{pkg}: 'available_versions' must be list")
            return None, None, None
        avail_map[pkg] = av[:]
        deps = info.get('dependencies', {})
        if deps is None:
            deps = {}
        if not isinstance(deps, dict):
            err(f"{pkg}: 'dependencies' must be an object mapping package->constraints")
            return None, None, None
        deps_map[pkg] = deps
    # incorporate dependency constraints into target packages
    for pkg, deps in deps_map.items():
        for dep_pkg, dep_constraints in deps.items():
            if isinstance(dep_constraints, str):
                dep_constraints = [dep_constraints]
            if not isinstance(dep_constraints, list):
                err(f"{pkg} dependency {dep_pkg} constraints must be string or list")
                return None, None, None
            if dep_pkg not in constraints_map:
                constraints_map.setdefault(dep_pkg, [])
                avail_map.setdefault(dep_pkg, [])
            for c in dep_constraints:
                if not isinstance(c, str):
                    err(f"{pkg} dependency constraint for {dep_pkg} is not string: {c}")
                    return None, None, None
                constraints_map.setdefault(dep_pkg, []).append(c.strip())
    return constraints_map, avail_map, deps_map

def pick_versions(constraints_map, avail_map):
    resolved = {}
    for pkg, cs in constraints_map.items():
        combined = ",".join(cs) if cs else ""
        try:
            spec = SpecifierSet(combined)
        except InvalidSpecifier as e:
            err(f"{pkg}: invalid specifier in {cs}: {e}")
            return None
        candidates = []
        for av in avail_map.get(pkg, []):
            try:
                v = Version(av)
            except InvalidVersion:
                # ignore unparseable available versions
                continue
            if cs and v not in spec:
                continue
            candidates.append(v)
        if not candidates:
            # If there are no constraints and availability exists, pick highest
            if not cs and avail_map.get(pkg):
                try:
                    best = max((Version(x) for x in avail_map[pkg]))
                    resolved[pkg] = str(best)
                    continue
                except Exception:
                    pass
            err(f"No available versions for {pkg} satisfy constraints: {cs}")
            return None
        best = max(candidates)
        resolved[pkg] = str(best)
    return resolved

def write_output(resolved, path='/app/resolved_versions.json'):
    try:
        with open(path, 'w') as f:
            if resolved is None:
                json.dump({"error": "No solution found"}, f, indent=2)
            else:
                json.dump(resolved, f, indent=2)
    except Exception as e:
        err(f"Failed to write output: {e}")
        return False
    return True

def main():
    data = load_constraints()
    if data is None:
        write_output(None)
        sys.exit(0)
    constraints_map, avail_map, deps_map = normalize_constraints(data)
    if constraints_map is None:
        write_output(None)
        sys.exit(0)
    resolved = pick_versions(constraints_map, avail_map)
    if resolved is None:
        write_output(None)
        sys.exit(0)
    # final validation
    for pkg, version in resolved.items():
        cs = constraints_map.get(pkg, [])
        combined = ",".join(cs) if cs else ""
        try:
            spec = SpecifierSet(combined)
        except InvalidSpecifier:
            write_output(None)
            sys.exit(0)
        try:
            v = Version(version)
        except InvalidVersion:
            write_output(None)
            sys.exit(0)
        if cs and v not in spec:
            err(f"Validation failed for {pkg} version {version} does not satisfy {cs}")
            write_output(None)
            sys.exit(0)
    write_output(resolved)
    print('/app/resolved_versions.json written.')

if __name__ == '__main__':
    main()
