#!/usr/bin/env python3
import json
import sys
from packaging.version import Version, InvalidVersion
from packaging.specifiers import SpecifierSet, InvalidSpecifier
from typing import Dict, List, Optional, Tuple

# A resolver that accepts either a simple constraints.json (pkg -> str or list)
# or a detailed one (pkg -> {"constraints": ..., "available_versions": [...], "dependencies": {...}}).
# It uses a backtracking search to find a global assignment of versions that satisfies
# all constraints and inter-package dependency requirements.

DEFAULT_AVAILABLE = {
    "numpy": ["1.19.0", "1.20.0", "1.21.0", "1.22.0", "1.23.0"],
    "pandas": ["1.3.0", "1.4.0", "1.5.0", "2.0.0"],
    "scikit-learn": ["0.24.0", "1.0.0", "1.1.0", "1.2.0"],
    "tensorflow": ["2.5.0", "2.6.0", "2.7.0", "2.8.0"],
    "torch": ["1.9.0", "1.10.0", "1.11.0", "1.12.0"]
}

DEFAULT_DEPENDENCIES = {
    "pandas": {"numpy": ">=1.20.0"},
    "scikit-learn": {"numpy": ">=1.19.0"},
    "tensorflow": {"numpy": ">=1.19.0"},
    "torch": {"numpy": ">=1.21.0"}
}

OUT_PATH = '/app/resolved_versions.json'
CONSTRAINTS_PATH = '/app/constraints.json'


def load_input(path: str) -> Optional[dict]:
    try:
        with open(path, 'r') as f:
            return json.load(f)
    except Exception as e:
        print(f"Error loading constraints: {e}")
        return None


def build_problem(data: dict) -> Tuple[Dict[str, str], Dict[str, List[str]], Dict[str, Dict[str, str]]]:
    # constraints_map: pkg -> combined spec string (comma-separated) or empty string
    # avail_map: pkg -> list of available version strings
    # deps_map: pkg -> dict(dep_pkg -> spec_str)
    constraints_map: Dict[str, str] = {}
    avail_map: Dict[str, List[str]] = {}
    deps_map: Dict[str, Dict[str, str]] = {}

    # start with defaults
    for pkg, vers in DEFAULT_AVAILABLE.items():
        avail_map[pkg] = list(vers)
    for pkg, deps in DEFAULT_DEPENDENCIES.items():
        deps_map[pkg] = dict(deps)

    if not isinstance(data, dict):
        raise ValueError("constraints.json must be a JSON object mapping package names to constraints or objects")

    for pkg, entry in data.items():
        # three possible shapes for entry: str, list, or dict
        if isinstance(entry, str):
            # a single spec string (may contain commas)
            constraints_map[pkg] = entry.strip()
        elif isinstance(entry, list):
            # list of spec strings
            joined = ','.join([str(x).strip() for x in entry])
            constraints_map[pkg] = joined
        elif isinstance(entry, dict):
            # detailed object: may contain 'constraints', 'available_versions', 'dependencies'
            c = entry.get('constraints')
            if isinstance(c, str):
                constraints_map[pkg] = c.strip()
            elif isinstance(c, list):
                constraints_map[pkg] = ','.join([str(x).strip() for x in c])
            elif c is None:
                # leave absent -> empty
                pass
            else:
                raise ValueError(f"Invalid 'constraints' for {pkg}")
            av = entry.get('available_versions')
            if av is not None:
                if not isinstance(av, list):
                    raise ValueError(f"'available_versions' for {pkg} must be a list if present")
                avail_map[pkg] = list(av)
            deps = entry.get('dependencies')
            if deps is not None:
                if not isinstance(deps, dict):
                    raise ValueError(f"'dependencies' for {pkg} must be an object if present")
                # convert values to strings
                deps_map[pkg] = {str(k): str(v) for k, v in deps.items()}
        else:
            raise ValueError(f"Invalid entry type for package {pkg}")

    # Ensure all packages mentioned in constraints exist in avail_map (if not, the package has no available versions)
    for pkg in list(constraints_map.keys()):
        if pkg not in avail_map:
            avail_map[pkg] = []

    # Ensure dependency target packages are present in avail_map
    for pkg, deps in deps_map.items():
        for dep in deps.keys():
            if dep not in avail_map:
                avail_map[dep] = []

    return constraints_map, avail_map, deps_map


def spec_allows(spec_str: str, version_str: str) -> bool:
    try:
        if not spec_str:
            return True
        spec = SpecifierSet(spec_str)
        v = Version(version_str)
        return v in spec
    except (InvalidSpecifier, InvalidVersion):
        return False


def backtrack(packages: List[str], avail_map: Dict[str, List[str]],
              constraints_map: Dict[str, str], deps_map: Dict[str, Dict[str, str]],
              assignment: Dict[str, str]) -> Optional[Dict[str, str]]:
    if len(assignment) == len(packages):
        return dict(assignment)

    # pick next package deterministically: use order from packages list
    for pkg in packages:
        if pkg not in assignment:
            target = pkg
            break

    # candidate versions: sort available versions by Version descending (prefer highest)
    candidates = []
    for av in avail_map.get(target, []):
        try:
            candidates.append((Version(av), av))
        except InvalidVersion:
            continue
    candidates.sort(reverse=True, key=lambda x: x[0])

    # If no available versions, cannot satisfy
    if not candidates:
        return None

    for _, ver_str in candidates:
        # quick check: does this version satisfy package's own constraints?
        specstr = constraints_map.get(target, "")
        if specstr and not spec_allows(specstr, ver_str):
            continue

        # check constraints imposed by already-assigned packages that depend on target
        ok = True
        for other, assigned_ver in assignment.items():
            # if other has dependency on target, check it
            deps = deps_map.get(other, {})
            if target in deps:
                dep_spec = deps[target]
                if not spec_allows(dep_spec, assigned_ver):
                    # The dependency declared by 'other' is on target version, but our representation
                    # stores dep spec about the dep package; correct check: does other require a constraint
                    # on target that assigned target version must match? We need to check target's candidate.
                    pass
                # specifically check candidate ver_str against dep_spec
                if not spec_allows(deps[target], ver_str):
                    ok = False
                    break
        if not ok:
            continue

        # tentatively assign and check the package's own dependencies where dependencies are already assigned
        assignment[target] = ver_str
        valid = True
        for dep_pkg, dep_spec in deps_map.get(target, {}).items():
            if dep_pkg in assignment:
                if not spec_allows(dep_spec, assignment[dep_pkg]):
                    valid = False
                    break
        if not valid:
            del assignment[target]
            continue

        # recurse
        res = backtrack(packages, avail_map, constraints_map, deps_map, assignment)
        if res is not None:
            return res

        # undo and try next candidate
        del assignment[target]

    return None


def write_output(result: Optional[Dict[str, str]], path: str = OUT_PATH) -> None:
    out = result if result is not None else {"error": "No solution found"}
    try:
        with open(path, 'w') as f:
            json.dump(out, f, indent=2)
    except Exception as e:
        print(f"Failed to write output: {e}")


def main():
    data = load_input(CONSTRAINTS_PATH)
    if data is None:
        write_output(None)
        sys.exit(0)
    try:
        constraints_map, avail_map, deps_map = build_problem(data)
    except ValueError as e:
        print(f"Error loading constraints: {e}")
        write_output(None)
        sys.exit(0)

    # Build list of packages to resolve: union of keys in avail_map and constraints_map and deps_map
    packages = sorted(set(list(avail_map.keys()) + list(constraints_map.keys()) + list(deps_map.keys())))

    # Run backtracking search
    result = backtrack(packages, avail_map, constraints_map, deps_map, {})

    write_output(result)
    if result is None:
        print(OUT_PATH + " written with error")
        sys.exit(0)
    else:
        print(OUT_PATH + " written with resolved versions")


if __name__ == '__main__':
    main()
