import base64, json

def xor_transform(data, key):
    kb = key.encode()
    return bytes([b ^ kb[i % len(kb)] for i, b in enumerate(data)])

def custom_shift(s):
    res = []
    for c in s:
        if 'a' <= c <= 'z':
            res.append(chr((ord(c) - ord('a') + 13) % 26 + ord('a')))
        elif 'A' <= c <= 'Z':
            res.append(chr((ord(c) - ord('A') + 13) % 26 + ord('A')))
        else:
            res.append(c)
    return ''.join(res)

def decode(encoded_b64, key):
    try:
        decoded_b64 = base64.b64decode(encoded_b64)
    except Exception as e:
        return None
    xor_rev = xor_transform(decoded_b64, key)
    s = xor_rev.decode('utf-8', errors='ignore')
    original = custom_shift(s)
    return original

